const PREP_SITE = {"hypocras-rouge":["Concasser grossièrement les épices⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧ au mortier pour libérer leurs arômes.","Verser le vin⟦I0⟧ dans un grand bocal, ajouter le sucre ou le miel⟦I1⟧ et remuer jusqu'à dissolution.","Ajouter les épices et l'eau de rose⟦I7⟧, fermer le bocal.","Laisser macérer à froid 24 à 48 heures, en remuant matin et soir.","Filtrer soigneusement à l'étamine, puis au filtre à café, jusqu'à obtenir un vin limpide.","Mettre en bouteille ; se déguste frais, en apéritif ou au dessert."],"hypocras-blanc":["Concasser les épices⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧ et les amandes⟦I6⟧ au mortier.","Mélanger le vin⟦I0⟧, le sucre ou le miel⟦I1⟧ et le zeste de citron⟦I7⟧ dans un bocal.","Ajouter les épices et amandes, fermer hermétiquement.","Macérer 24 à 48 heures à froid, en remuant deux fois par jour.","Filtrer jusqu'à parfaite limpidité.","Embouteiller et servir bien frais."],"vin-de-noix":["Rincer et essuyer les noix vertes⟦I0⟧, puis les couper en quartiers (port de gants conseillé, le brou tache).","Déposer les noix dans une grande bonbonne et verser le sucre⟦I3⟧ par-dessus.","Ajouter le vin rouge⟦I1⟧, puis l'eau-de-vie⟦I2⟧, la vanille⟦I4⟧ fendue, la cannelle⟦I5⟧ et le zeste d'orange⟦I6⟧.","Fermer hermétiquement et placer à l'abri de la lumière.","Macérer 40 jours, en remuant doucement tous les deux ou trois jours pour dissoudre le sucre.","Filtrer, mettre en bouteille. Attendre Noël pour la première dégustation ; meilleur après un à deux ans."],"vin-orange":["Brosser et couper les agrumes⟦I3⟧⟦I4⟧⟦I5⟧ en quartiers (sans les éplucher).","Réunir dans une bonbonne le vin⟦I0⟧, l'eau-de-vie⟦I1⟧, le sucre⟦I2⟧, les agrumes, la vanille⟦I6⟧ fendue et la cannelle⟦I7⟧.","Fermer et remuer pour amorcer la dissolution du sucre.","Macérer 40 à 60 jours, à l'abri de la lumière, en remuant doucement une fois par semaine.","Filtrer au chinois puis à l'étamine.","Mettre en bouteille ; se conserve jusqu'à deux ans."],"vin-de-peche":["Cueillir et rincer les feuilles de pêcher⟦I0⟧ (idéalement après les vendanges, lorsqu'elles sont parfumées).","Disposer les feuilles, le sucre⟦I2⟧ et l'eau-de-vie⟦I3⟧ dans un bocal.","Ajouter le vin rouge⟦I1⟧ et fermer hermétiquement.","Macérer une dizaine de jours au frais, à l'abri de la lumière, en remuant tous les deux jours.","Filtrer pour retirer les feuilles, puis embouteiller.","Patienter 15 jours à 3 semaines avant de déguster."],"troussepinette":["Cueillir les jeunes pousses de prunellier⟦I0⟧ (15 à 20 cm) juste après la floraison, en mai-juin.","Rincer puis déposer les pousses dans une bonbonne.","Ajouter le vin⟦I1⟧, l'eau-de-vie⟦I2⟧ et le sucre⟦I3⟧.","Fermer et macérer de 48 heures à un mois selon l'intensité souhaitée, en remuant régulièrement.","Filtrer soigneusement et mettre en bouteille.","Attendre deux à trois mois avant la dégustation."],"ratafia-cerises":["Mettre les griottes⟦I0⟧ (avec leurs noyaux) et les framboises⟦I1⟧ dans un grand bocal.","Ajouter la cannelle⟦I4⟧ et les clous de girofle⟦I5⟧, puis verser l'eau-de-vie⟦I2⟧.","Fermer et laisser macérer 15 jours à la lumière ambiante, en remuant de temps en temps.","Filtrer à travers un chinois.","Incorporer le sucre⟦I3⟧ en remuant longuement à la cuillère de bois jusqu'à dissolution complète.","Embouteiller et laisser reposer quelques semaines avant de déguster."],"creme-cassis":["Laver et égrener les cassis⟦I0⟧, puis les placer dans un grand récipient en verre.","Verser l'alcool⟦I1⟧ par-dessus, fermer, et laisser macérer 2 à 3 mois dans un endroit sombre et frais.","Écraser les baies pour en extraire le jus, puis filtrer à l'étamine en pressant bien.","Préparer un sirop avec le sucre⟦I2⟧ et l'eau⟦I3⟧, laisser refroidir.","Mélanger le sirop à l'alcool filtré jusqu'à obtenir une crème sirupeuse.","Embouteiller et laisser reposer 2 à 3 semaines avant de déguster."],"creme-mure":["Trier et laver rapidement les mûres⟦I0⟧, puis les déposer dans un bocal.","Couvrir d'alcool⟦I1⟧ et laisser macérer 5 à 6 semaines à l'obscurité.","Écraser et filtrer à l'étamine en pressant pour extraire tout le jus.","Confectionner un sirop sucre⟦I2⟧ + eau⟦I3⟧, laisser refroidir.","Mélanger sirop et alcool filtré.","Embouteiller et laisser reposer quelques semaines."],"vespetro":["Concasser grossièrement au mortier les graines d'angélique⟦I1⟧, de coriandre⟦I2⟧, de fenouil⟦I3⟧ et la badiane⟦I4⟧.","Mettre les graines et les zestes de citron⟦I5⟧ à macérer dans l'alcool⟦I0⟧ pendant une semaine, en remuant chaque jour.","Filtrer au tamis fin.","Préparer un sirop avec le sucre⟦I6⟧ et l'eau⟦I7⟧, laisser refroidir.","Mélanger le sirop à l'alcool aromatisé.","Embouteiller et laisser reposer avant dégustation."],"genepi":["Verser l'alcool⟦I2⟧ dans une grande bouteille en verre.","Ajouter les 40 brins de génépi⟦I0⟧ et les 40 morceaux de sucre⟦I1⟧.","Fermer et laisser macérer 40 jours, à l'abri de la lumière.","Filtrer puis mettre en jolies bouteilles.","On peut laisser 3 ou 4 brins dans la bouteille pour la décoration."],"liqueur-sureau":["Secouer les ombelles de sureau⟦I0⟧ sans les laver, pour préserver le pollen parfumé.","Mettre les fleurs, le zeste et le jus de citron⟦I2⟧ à macérer dans l'alcool⟦I1⟧, 2 à 3 semaines à l'abri de la lumière.","Filtrer à l'étamine.","Préparer un sirop avec le sucre⟦I3⟧ et l'eau⟦I4⟧, laisser refroidir.","Mélanger le sirop à l'alcool aromatisé.","Laisser reposer de 10 jours à 6 semaines avant de déguster."],"liqueur-44":["Laver l'orange⟦I0⟧ et y percer 44 trous à l'aide d'un pique.","Glisser un grain de café⟦I1⟧ dans chacun des 44 trous.","Déposer l'orange piquée dans un grand bocal avec le sucre⟦I2⟧.","Verser l'eau-de-vie⟦I3⟧, fermer le bocal.","Laisser macérer 44 jours, en remuant de temps en temps.","Retirer l'orange, filtrer et embouteiller."],"limoncello":["Prélever finement les zestes des citrons⟦I0⟧, sans la peau blanche amère.","Faire macérer les zestes dans l'alcool⟦I1⟧ une semaine, à l'abri de la lumière.","Filtrer pour retirer les zestes.","Préparer un sirop avec l'eau⟦I2⟧ et le sucre⟦I3⟧, laisser refroidir.","Mélanger le sirop à l'alcool citronné.","Embouteiller et conserver au congélateur ; servir très frais."],"guignolet":["Équeuter et laver les guignes⟦I0⟧, puis les déposer dans un bocal avec quelques noyaux concassés⟦I3⟧.","Verser l'eau-de-vie⟦I1⟧ et le sucre⟦I2⟧.","Fermer et macérer environ 2 mois, en remuant pour dissoudre le sucre.","Filtrer à l'étamine en pressant doucement les fruits.","Mettre en bouteille et laisser vieillir quelques mois."],"rhum-ananas-vanille":["Éplucher l'ananas⟦I1⟧ et le couper en morceaux.","Fendre la gousse de vanille⟦I2⟧ dans la longueur.","Disposer l'ananas, la vanille et le sucre⟦I3⟧ dans un bocal.","Verser le rhum⟦I0⟧, fermer le bocal.","Laisser macérer 2 à 3 mois dans un endroit sec et tempéré, à l'abri de la lumière, en agitant de temps en temps.","Goûter, ajuster le sucre si besoin, puis filtrer (ou laisser les fruits selon le goût)."],"eau-melisse-carmes":["Hacher la mélisse⟦I1⟧ et concasser les épices⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧.","Réunir mélisse, zeste de citron⟦I2⟧, épices et angélique⟦I7⟧ dans l'alcool⟦I0⟧.","Laisser macérer 4 jours (la recette véritable est ensuite distillée).","À défaut d'alambic, faire bouillir 5 minutes dans un peu d'eau, puis prolonger la macération 15 à 21 jours au soleil dans un bocal fermé.","Filtrer très finement.","Conserver en flacon ; se prend par cuillerées ou en gouttes sur un sucre."],"lq-amaretto":["Préparer un sirop avec le sucre⟦I6⟧ et l'eau⟦I1⟧, puis le laisser refroidir.","Réunir dans un bocal l'eau-de-vie⟦I0⟧, la vanille fendue⟦I2⟧, le citron⟦I3⟧, les amandes écrasées⟦I4⟧, le safran⟦I5⟧ et le sirop.","Macérer 60 jours au frais et à l'obscurité en remuant régulièrement.","Filtrer et mettre en bouteilles."],"lq-amaretto-cremino":["Préparer un sirop avec le sucre⟦I6⟧ et l'eau, laisser refroidir.","Réunir dans un bocal l'eau-de-vie⟦I1⟧, le lait⟦I0⟧, la vanille fendue⟦I2⟧, le citron⟦I3⟧, les amandes⟦I4⟧ et le safran⟦I5⟧ avec le sirop.","Macérer 60 jours au frais et à l'obscurité en remuant régulièrement.","Filtrer et mettre en bouteilles."],"lq-arancello":["Prélever les zestes d'orange⟦I0⟧ à l'économe et les faire macérer dans l'alcool⟦I1⟧ 2 mois.","Chauffer l'eau⟦I3⟧ pour y dissoudre le sucre⟦I2⟧.","Filtrer l'alcool pour retirer les zestes, puis y verser le sirop encore chaud.","Mettre en bouteilles."],"lq-arancello-cremino":["Prélever les zestes d'orange⟦I0⟧ à l'économe et les faire macérer dans l'alcool⟦I1⟧ 2 mois.","Chauffer le lait⟦I3⟧ pour y dissoudre le sucre⟦I2⟧.","Filtrer l'alcool, puis y verser la préparation lactée encore chaude.","Mettre en bouteilles."],"lq-limoncello-cremino":["Prélever les zestes de citron⟦I0⟧ à l'économe et les faire macérer dans l'alcool⟦I1⟧ 2 mois.","Chauffer le lait⟦I3⟧ pour y dissoudre le sucre⟦I2⟧.","Filtrer l'alcool, puis y verser la préparation lactée encore chaude.","Mettre en bouteilles."],"lq-anisette":["Dissoudre le sucre⟦I4⟧ dans un peu d'eau⟦I6⟧ tiède, laisser refroidir.","Réunir l'anis⟦I0⟧, la coriandre⟦I1⟧, la cannelle⟦I2⟧ et le macis⟦I3⟧ dans l'alcool⟦I5⟧ avec le sirop.","Macérer 2 mois en remuant régulièrement.","Filtrer et mettre en bouteilles."],"lq-amere-feuilles":["Dissoudre le sucre⟦I7⟧ dans l'eau⟦I8⟧ tiède, laisser refroidir.","Réunir toutes les feuilles et fleurs⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧ dans l'alcool⟦I6⟧, ajouter le sirop.","Macérer au minimum 8 semaines.","Filtrer et mettre en bouteilles."],"lq-anis-brizard":["Broyer les aromates⟦I2⟧⟦I3⟧⟦I4⟧ au mortier et les mélanger à l'alcool⟦I7⟧ avec l'essence d'anis⟦I0⟧ et le jus de citron⟦I1⟧.","Dissoudre le sucre⟦I5⟧ dans l'eau⟦I6⟧ tiède, laisser refroidir, puis l'ajouter à la préparation.","Macérer 4 semaines.","Filtrer ; laisser vieillir quelques mois avant de déguster."],"lq-ecorce-chene":["Broyer finement l'écorce de chêne⟦I3⟧.","Dissoudre le sucre⟦I2⟧ dans l'eau⟦I1⟧ chaude, ajouter la poudre de chêne, donner quelques bouillons et laisser refroidir.","Ajouter l'alcool⟦I0⟧.","Macérer 2 mois en agitant de temps en temps, puis filtrer."],"lq-bourgeons-sapin":["Verser l'eau-de-vie⟦I1⟧ sur les bourgeons⟦I0⟧ et laisser macérer 12 heures, puis filtrer.","Faire fondre le sucre⟦I2⟧ dans l'eau⟦I3⟧ et cuire le sirop jusqu'à la perle.","Mélanger le sirop refroidi à la macération.","Mettre en bouteilles."],"lq-douce-miel":["Diluer le miel⟦I0⟧ et l'eau⟦I3⟧, ajouter la vanille fendue⟦I1⟧.","Chauffer doucement 30 minutes sans bouillir, puis laisser refroidir.","Ajouter l'alcool⟦I2⟧ et mettre en bocal.","Laisser reposer au minimum 3 mois avant de déguster."],"lq-abricots":["Dénoyauter et découper les abricots⟦I1⟧ en morceaux ; casser quelques noyaux pour en récupérer les amandes.","Dissoudre le sucre⟦I2⟧ dans l'eau⟦I3⟧ chaude, laisser refroidir.","Réunir les fruits, les amandes des noyaux et le sirop dans l'alcool⟦I0⟧.","Macérer plusieurs semaines, puis filtrer."],"lq-abricots-secs":["Dissoudre le sucre⟦I2⟧ dans l'eau⟦I3⟧ chaude, laisser refroidir.","Couper les abricots⟦I0⟧ en quartiers.","Réunir dans l'alcool⟦I1⟧ les abricots, le sirop, la badiane⟦I5⟧, le zeste et le jus des oranges⟦I4⟧.","Macérer 2 mois, puis filtrer."],"lq-achillee":["Dissoudre le sucre⟦I2⟧ dans l'eau⟦I3⟧ chaude, laisser refroidir.","Réunir dans une jarre les fleurs d'achillée⟦I1⟧, le zeste et le jus du citron⟦I4⟧, et le sirop dans l'alcool⟦I0⟧.","Macérer 30 jours.","Filtrer et mettre en bouteilles."],"lq-amandes":["Dissoudre le sucre⟦I4⟧ dans l'eau⟦I5⟧ à ébullition lente, ajouter les poudres d'amande⟦I1⟧⟦I2⟧ et l'eau de fleur d'oranger⟦I3⟧.","Donner quelques bouillons, laisser reposer un jour, puis refroidir.","Ajouter l'alcool⟦I0⟧ dans une jarre hermétique.","Macérer 2 mois, puis filtrer."],"lq-aneth":["Dissoudre le sucre⟦I3⟧ dans l'eau⟦I2⟧ chaude, laisser refroidir.","Réunir les graines d'aneth⟦I0⟧, le sirop et l'alcool⟦I1⟧ dans une jarre.","Macérer 1 mois.","Filtrer et mettre en bouteilles."],"lq-artichauts":["Couper les tiges⟦I0⟧ en tronçons d'un centimètre.","Faire macérer tiges et feuilles⟦I1⟧ un mois dans l'alcool⟦I4⟧.","Préparer un sirop avec l'eau⟦I3⟧ et le sucre⟦I2⟧ et l'ajouter à la macération.","Laisser reposer 5 jours, puis filtrer."],"lq-bananes":["Peler et écraser les bananes⟦I3⟧, les couvrir d'alcool⟦I0⟧ et ajouter la vanille⟦I4⟧ fendue et ses graines.","Macérer 1 mois.","Ajouter le sirop (sucre⟦I1⟧ + eau⟦I2⟧) refroidi et prolonger 5 jours.","Passer au chinois, filtrer et mettre en bouteilles."],"lq-celeri":["Laver et couper les tiges de céleri⟦I0⟧ en petits tronçons.","Préparer un sirop avec l'eau⟦I4⟧ et le sucre⟦I5⟧.","Réunir dans une jarre le céleri, l'alcool⟦I3⟧, le sirop, la coriandre⟦I1⟧ ciselée et la badiane⟦I2⟧.","Macérer 20 jours, puis filtrer."],"lq-chataignes":["Laisser sécher les châtaignes⟦I0⟧ une à deux semaines, les décortiquer et broyer la chair.","Réunir dans une jarre la chair, l'alcool⟦I1⟧, la vanille⟦I2⟧ fendue et le sirop (sucre⟦I3⟧ + eau⟦I4⟧).","Macérer plusieurs mois dans un coin sombre.","Filtrer et mettre en bouteilles."],"lq-chevrefeuille":["Préparer un sirop avec l'eau⟦I3⟧ et le sucre⟦I1⟧.","Immerger les fleurs⟦I0⟧ dans le liquide chaud quelques heures.","Ajouter l'alcool⟦I2⟧ et mettre en jarre.","Macérer 2 mois, puis filtrer."],"lq-coco":["Dissoudre le sucre⟦I2⟧ dans le lait de coco⟦I1⟧ tiède, laisser refroidir.","Ajouter le rhum⟦I0⟧, puis la vanille⟦I3⟧, l'amande amère⟦I4⟧, la cannelle⟦I5⟧, le zeste et le jus de citron vert⟦I6⟧ et le macis⟦I7⟧.","Verser en jarre.","Macérer au minimum 3 mois."],"lq-epices":["Broyer les épices⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧ au mortier.","Dissoudre le sucre⟦I9⟧ dans l'eau⟦I10⟧ chaude, laisser refroidir.","Réunir les épices, l'aneth⟦I7⟧ et le sirop dans une bonbonne, ajouter l'alcool⟦I8⟧.","Macérer 3 mois en remuant régulièrement, puis filtrer."],"lq-fenouil-sauvage":["Mettre les sommités de fenouil⟦I0⟧ dans l'alcool⟦I1⟧.","Préparer un sirop avec le sucre⟦I2⟧ et l'eau⟦I3⟧, laisser refroidir.","Mélanger le sirop à l'alcool.","Macérer 2 mois, puis filtrer."],"lq-fraises-tagada":["Faire dissoudre doucement les fraises Tagada⟦I1⟧ dans l'eau⟦I0⟧ à petit bouillon, laisser refroidir.","Incorporer doucement l'alcool⟦I2⟧ en remuant.","Macérer 10 jours.","Filtrer et mettre en bouteilles."],"lq-fleur-oranger":["Chauffer l'eau⟦I3⟧ pour dissoudre le sucre⟦I2⟧, laisser refroidir complètement.","Réunir toutes les fleurs⟦I0⟧, le sirop et l'eau de fleur d'oranger⟦I4⟧ dans l'alcool⟦I1⟧.","Mettre en jarre.","Macérer 2 mois, puis filtrer."],"lq-acacias":["Faire une décoction des fleurs⟦I2⟧ 15 minutes avec le sucre⟦I0⟧ et l'eau⟦I1⟧, laisser reposer 12 heures.","Ajouter l'alcool⟦I3⟧, la cannelle⟦I4⟧ et le girofle⟦I5⟧.","Macérer 2 semaines au soleil.","Filtrer ; laisser vieillir au minimum 2 mois."],"lq-alise":["Faire macérer 8 semaines les fruits⟦I0⟧, la cannelle⟦I3⟧, la vanille⟦I4⟧ fendue et le sucre⟦I2⟧ dilué dans l'eau⟦I5⟧.","Filtrer.","Laisser reposer une semaine après l'ajout du sirop.","Filtrer une dernière fois ; vieillir au minimum 2 mois."],"lq-alkermes":["Broyer les épices⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧.","Réunir épices et alcool⟦I6⟧, exposer 2 semaines au soleil en agitant chaque jour.","Ajouter un sirop de sucre⟦I7⟧ et d'eau⟦I8⟧, laisser reposer un jour, puis filtrer.","Parfumer à l'eau de rose⟦I9⟧ (et colorer à la cochenille⟦I10⟧ si désiré)."],"lq-noyaux-peches":["Mettre les noyaux entiers, plus 5 noyaux de pêches⟦I1⟧ et 10 d'abricots⟦I0⟧ concassés, en bocal avec la vanille⟦I3⟧.","Macérer 2 mois à l'extérieur, au soleil, puis filtrer.","Ajouter le sirop tiède et laisser reposer une semaine.","Filtrer une dernière fois."],"lq-ananas":["Éplucher l'ananas⟦I0⟧ et le couper en dés.","Macérer un mois dans l'eau-de-vie⟦I1⟧.","Filtrer en pressant pour extraire le jus, puis ajouter le sucre de canne⟦I2⟧.","Laisser reposer une semaine, filtrer et servir frais."],"lq-angelique":["Faire macérer 2 mois l'angélique⟦I0⟧, les graines⟦I1⟧ et les épices⟦I2⟧⟦I3⟧⟦I4⟧ dans l'eau-de-vie⟦I5⟧.","Filtrer en pressant.","Ajouter le sirop⟦I6⟧⟦I7⟧ tiède et laisser reposer une semaine.","Filtrer ; vieillir quelques semaines."],"lq-angleterre":["Monder les amandes⟦I1⟧, zester finement le citron⟦I2⟧, broyer les aromates⟦I3⟧⟦I4⟧⟦I5⟧ au mortier.","Réunir le tout dans l'alcool⟦I0⟧ et macérer 30 jours en agitant régulièrement.","Ajouter le sirop de sucre⟦I6⟧ et d'eau⟦I7⟧, laisser reposer quelques jours en remuant.","Filtrer."],"lq-anis":["Préparer un sirop avec l'eau⟦I6⟧ et le sucre⟦I5⟧.","Réunir tous les ingrédients⟦I0⟧⟦I2⟧⟦I3⟧⟦I4⟧ dans l'alcool⟦I1⟧ avec le sirop.","Macérer 2 mois en agitant régulièrement.","Filtrer, laisser reposer quelques jours, puis filtrer fin."],"lq-asperule":["Cueillir les fleurs⟦I0⟧ en début de floraison (mai) et les laver.","Préparer un sirop avec le sucre⟦I1⟧ et l'eau⟦I3⟧, laisser refroidir.","Réunir l'alcool⟦I2⟧, les fleurs et le sirop.","Macérer 2 mois à l'obscurité, puis filtrer."],"lq-aubepine":["Écraser l'aubépine⟦I0⟧ et la mélanger aux amandes⟦I1⟧ broyées.","Ajouter l'alcool⟦I2⟧ et le sucre⟦I3⟧ dilué dans le verre d'eau⟦I4⟧.","Macérer 4 semaines.","Filtrer et mettre en bouteilles."],"lq-basilic":["Faire macérer les feuilles⟦I1⟧ dans l'alcool⟦I0⟧ 2 mois (bocal fermé, à l'obscurité).","Préparer un sirop⟦I2⟧⟦I3⟧, le laisser refroidir et le mélanger.","Laisser reposer au moins 8 jours.","Filtrer et mettre en bouteilles."],"lq-betterave":["Découper la betterave⟦I3⟧ crue en cubes.","Réunir avec l'alcool⟦I0⟧ et le sucre⟦I1⟧ dilué dans l'eau⟦I2⟧.","Macérer 15 jours.","Filtrer et mettre en bouteilles."],"lq-bissap":["Faire une décoction des fleurs d'hibiscus⟦I0⟧ 30 minutes, dissoudre le sucre⟦I2⟧.","Laisser refroidir, puis ajouter l'alcool⟦I1⟧.","Macérer 4 semaines à l'ombre.","Filtrer et mettre en bouteilles."],"lq-bouillon-blanc":["Remplir un bocal d'alcool⟦I0⟧ et y ajouter les fleurs⟦I1⟧ en pressant.","Macérer un mois, puis filtrer.","Ajouter le sirop⟦I2⟧⟦I3⟧ froid et laisser reposer quelques jours.","Filtrer une dernière fois."],"rh-44":["Percer l'orange⟦I1⟧ et y insérer les 44 grains de café⟦I2⟧.","Verser le rhum⟦I0⟧ dans un bocal, ajouter la vanille⟦I4⟧ fendue et le sucre de canne⟦I3⟧.","Suspendre l'orange au-dessus du rhum avec une gaze et une ficelle.","Macérer 44 jours."],"rh-vanille-macadamia":["Fendre les gousses de vanille⟦I1⟧ et récupérer les graines.","Réunir en bocal la vanille, ses graines, les noix de Macadamia⟦I2⟧, le sucre⟦I3⟧ et le rhum⟦I0⟧.","Macérer 3 mois en secouant régulièrement."],"rh-ananas":["Éplucher l'ananas⟦I0⟧ (retirer les yeux) et le couper en morceaux adaptés au goulot.","Placer en bocal avec le sucre de canne⟦I1⟧ et le rhum⟦I2⟧.","Fermer hermétiquement et macérer 8 semaines."],"rh-vaudou":["Couper les fruits⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ finement et broyer les épices sèches⟦I5⟧⟦I6⟧⟦I8⟧⟦I9⟧⟦I10⟧⟦I11⟧.","Réunir tous les ingrédients⟦I0⟧⟦I7⟧ en bocal avec le rhum⟦I12⟧.","Retirer les piments après un mois.","Poursuivre la macération jusqu'à 4 mois au total."],"rh-banane":["Couper les bananes⟦I0⟧ en morceaux et les mettre en bocal.","Ajouter le rhum agricole⟦I1⟧ et le sirop de canne⟦I2⟧.","Macérer 3 mois."],"rh-abricots-antilles":["Détailler la chair des abricots⟦I0⟧ et casser les noyaux.","Ajouter la vanille⟦I2⟧ fendue et ses graines grattées.","Réunir le tout en bocal avec le rhum⟦I3⟧ et le sucre⟦I1⟧.","Macérer 3 mois."],"rh-cerise-citronnee":["Éplucher le citron⟦I2⟧ (retirer le blanc) et le couper en tranches avec son zeste.","Couper les cerises⟦I1⟧ en deux en conservant quelques noyaux écrasés.","Réunir en bocal avec la vanille⟦I3⟧ fendue et le sucre⟦I4⟧.","Retirer le citron après un mois ; macérer 90 jours au total."],"rh-acai":["Réduire grossièrement le poivre⟦I4⟧ et la cannelle⟦I3⟧ en poudre.","Légèrement broyer les baies d'açaï⟦I0⟧.","Réunir épices, baies, sirop⟦I2⟧ et rhum⟦I1⟧ en bocal.","Macérer 2 mois."],"rh-couille-singe-tagada":["Mettre les bonbons⟦I1⟧ et les fraises Tagada⟦I0⟧ en bocal.","Verser le rhum⟦I2⟧.","Remuer et laisser macérer en secouant régulièrement jusqu'à dissolution."],"rh-acerola":["Laver les fruits⟦I0⟧ et les couper en tronçons.","Réunir en bocal le sirop⟦I2⟧, les fruits et le rhum⟦I1⟧.","Macérer 2 mois, puis filtrer et mettre en bouteille."],"rh-hibiscus":["Verser le rhum⟦I2⟧ en bocal en laissant un peu d'espace.","Ajouter les fleurs d'hibiscus⟦I0⟧ et le sucre de canne⟦I1⟧, remuer doucement.","Fermer hermétiquement et macérer 3 mois minimum."],"rh-ananas-piment":["Découper et peler l'ananas⟦I0⟧, broyer légèrement les piments⟦I3⟧.","Réunir le tout en bocal avec le sucre⟦I1⟧ et le rhum⟦I2⟧.","Macérer 2 mois à l'ombre."],"rh-fraise":["Équeuter les fraises⟦I1⟧ et les couper en quartiers.","Les placer dans un grand bocal avec le rhum⟦I0⟧ et le sucre de canne⟦I2⟧.","Macérer 3 mois en remuant régulièrement."],"rh-arbouses":["Laver les arbouses⟦I0⟧ et les couper en quartiers.","Réunir en bocal avec le thym⟦I1⟧, le sucre⟦I2⟧ et le rhum⟦I3⟧.","Macérer 6 semaines."],"rh-cacahuete":["Mixer les cacahuètes⟦I0⟧, les deux laits⟦I2⟧⟦I3⟧ et les épices⟦I4⟧⟦I5⟧ jusqu'à texture lisse.","Chauffer à feu moyen 5 minutes en remuant.","Ajouter le rhum⟦I1⟧, laisser refroidir.","Mettre en bouteille ; reposer 5 à 6 jours."],"rh-mangue-betterave":["Éplucher et couper la mangue⟦I0⟧ et la betterave⟦I1⟧ en petits morceaux.","Réunir en bocal avec le rhum agricole⟦I2⟧ et le sucre⟦I3⟧.","Bien mélanger et macérer 3 mois."],"rh-banane-cannelle":["Faire un caramel léger avec le sirop⟦I2⟧, y ajouter la vanille⟦I3⟧ fendue et ses graines.","Laisser refroidir et dissoudre dans le rhum⟦I0⟧.","Ajouter la cannelle⟦I4⟧ et les bananes sèches⟦I1⟧.","Macérer 8 semaines."],"rh-menthe-sauvage":["Mettre le rhum⟦I1⟧ en bocal, ajouter la menthe⟦I0⟧ et le sucre de canne⟦I2⟧.","Remuer régulièrement.","Macérer 2 mois à l'ombre et au sec."],"rh-poire":["Éplucher les poires⟦I0⟧, retirer les pépins et les couper en petits morceaux.","Réunir en bocal avec le rhum⟦I1⟧ et le sucre de canne⟦I2⟧.","Bien mélanger et macérer 3 mois."],"rh-bounty":["Couper les Bounty⟦I0⟧ en deux.","Les ajouter au rhum⟦I1⟧ en bouteille.","Conserver en endroit sombre et sec ; macérer 2 mois."],"rh-coco-vanille":["Percer la noix de coco⟦I1⟧ (22 mm) et en vider l'eau.","Glisser la gousse de vanille⟦I2⟧ à l'intérieur et la remplir de rhum⟦I0⟧.","Macérer 3 mois."],"rh-tonka":["Broyer les fèves de tonka⟦I0⟧ au mortier.","Réunir tous les ingrédients en bocal.","Macérer un mois minimum."],"rh-gingembre":["Rompre la cannelle⟦I3⟧, fendre la vanille⟦I1⟧ et récupérer les graines.","Laver le gingembre⟦I2⟧ et le couper en petits morceaux.","Réunir le tout dans le rhum⟦I0⟧.","Macérer 3 mois en remuant une fois par semaine."],"rh-raisin-muscat":["Écraser les raisins⟦I0⟧ en conservant pulpe, peaux et pépins.","Ajouter le sirop de canne⟦I1⟧, la cannelle⟦I4⟧ et les figues⟦I3⟧.","Couvrir de rhum blanc⟦I2⟧.","Macérer 6 semaines."],"rh-figues-fraiches":["Broyer finement les épices⟦I1⟧⟦I2⟧ au mortier.","Réunir tous les éléments en bocal.","Macérer 8 semaines en remuant chaque semaine."],"rh-abricots":["Couper les abricots⟦I0⟧ et les mettre en bocal avec leurs noyaux broyés.","Ajouter le rhum⟦I1⟧ et le sucre⟦I2⟧, bien remuer.","Conserver à l'ombre et au sec ; macérer 2 mois."],"rh-epices":["Laver et peler le gingembre⟦I9⟧, fendre la vanille⟦I6⟧ et récupérer les graines.","Réunir tous les ingrédients en bocal avec le rhum⟦I0⟧.","Macérer 3 mois."],"rh-fraises-tagada":["Couper les fraises Tagada⟦I1⟧ en morceaux.","Les laisser fondre et macérer dans le rhum⟦I0⟧ 1 mois.","Filtrer et mettre en bouteille."],"rh-kiwis-jaunes":["Laver les kiwis⟦I1⟧ et les couper en fines tranches.","Réunir en bocal avec le sirop⟦I0⟧ et le rhum⟦I2⟧.","Macérer 2 mois."],"rh-pommes-tatin":["Couper les pommes⟦I1⟧ en quartiers et les faire revenir à sec.","Réunir en bocal pommes, vanille fendue⟦I2⟧, sirop⟦I3⟧ et rhum⟦I0⟧.","Filtrer le dépôt après deux semaines.","Macérer 2 mois à l'ombre."],"rh-brulant":["Mettre les piments⟦I0⟧ en bocal et les ramollir dans le rhum⟦I2⟧.","Macérer environ 30 jours.","Ajouter ensuite la cannelle⟦I3⟧ et le sucre de canne⟦I1⟧."],"rh-cafe-vanille":["Broyer grossièrement les grains de café⟦I0⟧ au mortier.","Fendre la vanille⟦I1⟧ et récupérer les graines.","Réunir café, vanille et rhum⟦I2⟧ en bocal.","Macérer 2 mois."],"rh-canneberge-framboise":["Broyer légèrement les canneberges⟦I1⟧ et couper les framboises⟦I2⟧.","Fendre la vanille⟦I3⟧ et récupérer les graines.","Réunir tous les ingrédients dans un grand bocal.","Macérer 3 mois."],"rh-caramel":["Verser le sirop de canne⟦I2⟧ en bocal, ajouter les Carambars⟦I1⟧ en tronçons puis le rhum⟦I0⟧.","Secouer tous les 2-3 jours jusqu'à dissolution.","Macérer 2 mois à l'ombre."],"rh-cassis-groseille":["Broyer légèrement le cassis⟦I1⟧ et la groseille⟦I2⟧ au mortier.","Réunir en bocal avec le rhum⟦I3⟧ et le sirop⟦I0⟧ ; macérer 60 jours.","Ajouter la cannelle⟦I4⟧ broyée et macérer 30 jours de plus."],"rh-citron-gingembre":["Couper les citrons⟦I0⟧⟦I1⟧ et émincer le gingembre⟦I2⟧.","Réunir en bocal avec le rhum⟦I3⟧ et le sirop⟦I4⟧.","Macérer 30 jours."],"rh-citron-gingembre-piment":["Couper le gingembre⟦I1⟧ en fines tranches.","Réunir en bocal le rhum⟦I4⟧, le sirop⟦I3⟧, le gingembre et les écorces de citron vert⟦I0⟧.","Retirer le piment⟦I2⟧ après 30 jours.","Ajouter le zeste de citron vert 15 jours avant dégustation."],"rh-coco-gingembre":["Ouvrir la noix de coco⟦I0⟧, recueillir le jus et couper la chair en dés.","Réunir tous les ingrédients en bocal.","Macérer 3 mois."],"rh-des-bois":["Laver et préparer les fruits⟦I1⟧⟦I2⟧ et la menthe⟦I6⟧ ; fendre la vanille⟦I4⟧.","Chauffer la cannelle⟦I3⟧ légèrement broyée à sec 5 minutes.","Réunir tous les ingrédients en bocal, arroser de sirop⟦I5⟧ puis de rhum⟦I0⟧.","Macérer 8 semaines en remuant une fois par semaine."],"rh-douceur":["Couper les oranges⟦I0⟧ et les mettre en bocal.","Broyer la cannelle⟦I2⟧ et le girofle⟦I1⟧ au mortier.","Réunir le tout et recouvrir de rhum⟦I3⟧.","Macérer 2 mois."],"rh-violette":["Casser les bonbons à la violette⟦I0⟧.","Les mettre dans le rhum⟦I1⟧ avec l'eau⟦I2⟧.","Laisser fondre et macérer jusqu'à dissolution complète."],"rh-fraise-menthe":["Broyer légèrement les fraises⟦I1⟧.","Réunir tous les ingrédients en bocal.","Macérer 4 mois minimum."],"rh-fraise-basilic":["Découper les fraises fraîches⟦I1⟧ et séchées⟦I2⟧, rincer le basilic⟦I6⟧.","Fendre la vanille⟦I4⟧ et prélever de gros zestes de citron vert⟦I3⟧.","Réunir le tout en bocal avec le rhum⟦I0⟧ et le sucre⟦I5⟧.","Macérer 3 mois."],"rh-kiwi-banane":["Éplucher et couper les kiwis⟦I1⟧ et la banane⟦I2⟧.","Réunir en bocal avec les sucres⟦I3⟧⟦I4⟧, la vanille⟦I5⟧ et le miel⟦I6⟧.","Verser le rhum⟦I0⟧ et macérer 2 mois."],"rh-kiwi-poire-noisette":["Couper le kiwi⟦I0⟧ et la poire⟦I2⟧ en fines tranches.","Réunir en récipient avec les noisettes⟦I1⟧.","Verser le sirop de canne⟦I3⟧ et le rhum⟦I4⟧, bien remuer.","Macérer 3 mois."],"rh-mangues-bananes-flambees":["Caraméliser le sucre⟦I4⟧, dorer les bananes⟦I0⟧ coupées en deux puis les flamber au rhum⟦I3⟧.","Laisser refroidir, couper la mangue⟦I1⟧, fendre la vanille⟦I2⟧.","Réunir le tout en bocal et ajouter le rhum à 50°.","Macérer 4 mois minimum."],"rh-mangues-framboises":["Couper la mangue⟦I0⟧ en petits morceaux.","Alterner en bocal des couches de mangue et de framboises⟦I1⟧, en nappant de sirop de canne⟦I2⟧.","Verser le rhum⟦I3⟧.","Macérer 3 mois."],"rh-mangues-passion":["Éplucher les mangues⟦I1⟧ et les couper en petits morceaux.","Ajouter l'intérieur des fruits de la passion⟦I2⟧, la cannelle⟦I4⟧, la vanille⟦I3⟧ et le sucre⟦I5⟧.","Verser le rhum⟦I0⟧.","Macérer 2 mois."],"rh-myrtilles-miel":["Fendre la vanille⟦I2⟧ et retirer les graines.","Réunir tous les ingrédients en bocal et bien remuer.","Macérer 2 mois en remuant jusqu'à dissolution du miel⟦I1⟧."],"rh-noisettes":["Émonder et éplucher les noisettes⟦I0⟧ (eau bouillante 1 minute, puis refroidir).","Réunir noisettes et vanille⟦I2⟧ fendue en bocal, arroser de rhum⟦I1⟧.","Macérer 6 mois minimum."],"rh-orange-cannelle-vanille":["Prélever finement les peaux d'orange⟦I1⟧ à l'économe (sans blanc).","Fendre la vanille⟦I3⟧ et prélever les graines.","Réunir en bocal le rhum⟦I0⟧, le sucre⟦I4⟧, la vanille et les peaux d'orange.","Macérer 3 mois minimum à l'ombre."],"rh-pamplemousse-menthe":["Éplucher les pamplemousses⟦I1⟧, retirer le blanc et couper en quartiers.","Réunir en bocal avec la menthe⟦I2⟧, la cassonade⟦I3⟧ et le rhum⟦I0⟧.","Retirer la menthe après 3-4 jours.","Macérer 60 jours."],"rh-peches-citrons-verts":["Dénoyauter les pêches⟦I1⟧ et concasser les noyaux, couper la chair en petits dés.","Réunir tous les ingrédients en bocal et macérer une semaine.","Ajouter le sirop de cassonade⟦I0⟧ et prolonger 2 mois."],"rh-peches-poires-framboises":["Laver, éplucher, dénoyauter et épépiner les pêches⟦I1⟧ et les poires⟦I2⟧, couper en quartiers.","Disposer les fruits en bocal.","Ajouter le sucre de canne⟦I4⟧ puis le rhum⟦I0⟧.","Macérer 2 mois."],"rh-vanille-cafe":["Fendre la vanille⟦I1⟧ et gratter les graines.","Concasser légèrement le café⟦I0⟧ au mortier.","Réunir en bocal vanille, café, sucre⟦I3⟧ et rhum⟦I2⟧.","Macérer 3 mois minimum à l'ombre."],"rh-vanille-citrons-verts":["Fendre la vanille⟦I1⟧ et récupérer les graines.","Réunir en bocal le citron vert⟦I2⟧, le sirop⟦I0⟧, la vanille et le rhum⟦I3⟧.","Macérer 3 mois, puis filtrer et mettre en bouteille."],"rh-atemoya":["Extraire la pulpe des atémoyas⟦I0⟧ et retirer les graines noires.","Peler les bananes⟦I3⟧ et les couper en tronçons.","Réunir fruits, cannelle⟦I4⟧ et sirop⟦I1⟧ en bocal, couvrir de rhum⟦I2⟧.","Macérer 6 semaines minimum."],"rh-banane-sechee":["Faire un caramel léger avec le sirop⟦I1⟧, y ajouter la vanille⟦I2⟧ fendue et ses graines.","Laisser refroidir et dissoudre dans le rhum⟦I3⟧.","Ajouter la cannelle⟦I4⟧ et les bananes sèches⟦I0⟧.","Macérer 8 semaines."],"rh-carambole":["Laver les caramboles⟦I0⟧ et les débiter en fines tranches, découper la rhubarbe⟦I3⟧.","Réunir tous les ingrédients dans le rhum⟦I2⟧.","Macérer 6 semaines."],"rh-casse-fistula":["Extraire les pastilles des cosses de casse fistula⟦I0⟧.","Réunir tous les ingrédients dans le rhum⟦I2⟧.","Macérer 6 semaines minimum."],"rh-cempedak":["Ouvrir le cempedak⟦I0⟧ et peler les fruits intérieurs.","Écraser la citronnelle⟦I1⟧ et la cannelle⟦I3⟧.","Réunir en bocal et recouvrir de rhum⟦I4⟧.","Macérer 5 à 6 semaines en remuant régulièrement."],"rh-corossol":["Peler les fruits⟦I0⟧ et récupérer la chair sans pépins.","Broyer finement les épices⟦I3⟧⟦I4⟧.","Réunir en bocal et couvrir de rhum⟦I2⟧.","Macérer 6 semaines, puis filtrer."],"rh-dattes":["Ouvrir les dattes⟦I0⟧ et retirer les noyaux.","Broyer les épices⟦I1⟧⟦I2⟧.","Réunir en bocal avec le rhum⟦I3⟧.","Macérer 6 semaines à l'abri de la lumière."],"rh-feijoa":["Broyer les épices⟦I2⟧⟦I3⟧ au mortier.","Laver et découper les feijoas⟦I0⟧ en tranches.","Réunir le tout en bocal avec le sirop⟦I1⟧ et le rhum⟦I4⟧.","Macérer 8 semaines."],"lq-liqueur-de-cacao":["Faire un sirop, le laisser refroidir et mélanger tous les ingrédients dans l’alcool⟦I0⟧ Fendre la vanille⟦I5⟧ et briser la cannelle⟦I4⟧.","Laisser bien macérer le tout pendant au moins 3 mois en remuant régulièrement, car le chocolat à tendance à faire pâte.","Filtrer la préparation, laisser décanter quelques jours, filtrer à nouveau et mettre en bouteilles."],"lq-liqueur-de-cafe":["Placer les grains de café⟦I0⟧ avec l’alcool⟦I1⟧ dans un récipient hermétique.","Laisser macérer pendant 20 jours en mélangeant une fois par jour.","Au bout des 20 jours, préparer un sirop de sucre :.","Mélanger l’eau⟦I3⟧ et le sucre⟦I2⟧ dans une casserole.","Porter à ébullition et laisser réduire jusqu’à obtention d’un sirop.","Ajouter le sirop au mélange café et alcool.","Laisser à nouveau macérer pendant 10 jours.","Filtrer le mélange et embouteiller.","Attendre 1 mois avant de servir."],"lq-liqueur-de-camomille":["Laisser macérer les fleurs⟦I3⟧ 4 semaines dans l’alcool⟦I0⟧.","Préparer le sirop avec l’eau⟦I1⟧ et le sucre⟦I2⟧ puis l’ajouter froid à la macération.","Faire décanter une semaine puis filtrer finement et mettre en bouteilles."],"lq-liqueur-de-cannelle-1":["Mélanger les alcools⟦I1⟧⟦I2⟧ et ajouter la cannelle⟦I0⟧ finement broyée.","Dissoudre le sucre⟦I3⟧ dans un verre d’eau⟦I4⟧ et l’ajouter à la préparation.","Laisser doucement macérer au moins 2 mois.","Filtrer et mettre en bouteilles cet alcool très parfumé, qui se marie magnifiquement avec les salades de fruits et les pâtisseries."],"lq-liqueur-de-cannelle-2":["Broyer au mortier la cannelle⟦I1⟧, et la mettre dans une jarre.","Verser dessus l’alcool⟦I0⟧, puis Ajouter la vanille⟦I3⟧ fendue.","Dissoudre le sucre⟦I4⟧ dans le verre d’eau⟦I5⟧ et l’ajouter à la préparation.","Peler les pommes⟦I2⟧, les débiter en petit quartiers et les mélanger dans la jarre.","Laisser reposer à l’ombre pendant 2 mois.","Passer ce temps passer et bien exprimer tout le jus.","Filtrer finement et mettre en bouteilles.","Cet alcool fin et parfumé accompagnera divinement le riz au lait par exemple."],"lq-liqueur-de-carvi":["Faire macérer les graine de carvi⟦I0⟧ pendant un mois dans l’eau de vie⟦I1⟧ dans un endroit tiède.","Ajouter le sirop préparé avec l’eau⟦I2⟧ et le sucre⟦I3⟧ candi.","Laisser reposer une semaine et filtrer la préparation.","Mettre en bouteilles.","Laisser reposer quelques semaines avant de consommer."],"lq-liqueur-de-cassis-1":["Egrapper les cassis⟦I0⟧, les ébarber et les mettre dans un bocal fermant bien.","Préparer le sirop et le verser froid sur les fruits, Ecraser vigoureusement les baies puis verser l’alcool⟦I3⟧.","Fermer le bocal et laisser au moins 3 mois dans un endroit sombre.","Mélanger régulièrement la macération.","Filtrer le mélange et laisser reposer 2 ou 3 jours, filtrer de nouveau et mettre en bouteilles."],"lq-liqueur-de-cassis-2":["Laver et égoutter les fruits⟦I0⟧⟦I1⟧ et les verser dans un bocal contenant l’alcool⟦I2⟧.","Ajouter les épices⟦I5⟧⟦I6⟧ le sirop refroidi⟦I3⟧⟦I4⟧ et les épices.","Laisser macérer et remuant très souvent pendant au moins 2 mois.","Filtrer la préparation plusieurs fois pour bien clarifier le mélange.","Mettre en bouteilles et laisser reposer quelques semaines avant de consommer."],"lq-liqueur-de-cerfeuil":["Faire macérer dans l’alcool⟦I0⟧, le cerfeuil⟦I5⟧, l’absinthe⟦I4⟧ (ou de la badiane), la menthe⟦I3⟧.","Mettre le mélange 4 semaines dans une jarre à l’ombre.","Filtrer le mélange puis incorporer le sirop bien refroidi⟦I2⟧⟦I1⟧, laisser décanter quelques jours puis filtrer et mettre en bouteilles."],"lq-liqueur-de-cerises-noires":["Dénoyauter les cerises⟦I0⟧ et les écraser dans un bocal fermant bien, concasser la moitié des noyaux.","Mettre les fruits et les noyaux concassés dans un bocal, couvrir d’eau de vie⟦I1⟧ et laisser macérer un mois.","Passer le mélange en exprimant bien tout le jus, faire un sirop avec le sucre et l’eau⟦I2⟧⟦I3⟧ et l’incorporer encore tiède à la préparation.","Laisser décanter quelques jours, filtrer et mettre en bouteilles.","Laisser reposer quelques semaines avant de consommer bien frais."],"lq-liqueur-facon-chartreuse-jaune":["Laisser macérer tous les ingrédients⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧ dans l’alcool⟦I0⟧ pendant 4 semaines dans une bonbonne fermant bien.","Ensuite filtrer la préparation puis ajouter le sirop de sucre froid⟦I8⟧⟦I7⟧.","Laisser décanter quelques jours filtrer de nouveau et mettre en bouteilles.","Faire vieillir au moins 6 mois avant de consommer."],"lq-liqueur-facon-chartreuse-verte":["Mettre tout les éléments dans l’alcool⟦I10⟧, dissoudre le sucre⟦I12⟧ dans l’eau⟦I11⟧ avec le safran⟦I8⟧ et laisser refroidir.","Dans une jarre faire macérer différentes feuilles⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧, les branches d’angélique tronçonnées⟦I9⟧ et le sirop safrané.","Mettre au repos dans un endroit sombre pendant 8 semaines.","Filtrer finement et mettre en bouteilles."],"lq-liqueur-de-cherry-brandy":["Laver, sécher et équeuter les cerises⟦I2⟧⟦I3⟧ ; écraser les grossièrement en brisant les noyaux.","Passer les framboises⟦I4⟧ au mixer.","Mettre ces fruits dans une casserole anti-adhérente avec l'eau de vie⟦I0⟧ le bâton de cannelle⟦I5⟧ et les clous de girofle⟦I6⟧.","Amener à ébullition sur feu moyen.","Après quelques bouillons, verser dans un grand bocal.","Laisser refroidir et boucher.","Laisser macérer au frais pendant un mois.","Passé ce délai, faire un sirop avec le sucre⟦I7⟧ et un litre d'eau.","Faire cuire 2 mn à gros bouillons sans cesser de remuer.","Laisser refroidir.","Filtrer le contenu du bocal, ajouter le sirop refroidi et le kirsch⟦I1⟧.","Filtrer et mettre en bouteilles.","Boucher soigneusement et attendre un bon mois avant de consommer.","Garder à l'abri de la lumière.","Cette liqueur se bonifie en vieillissant."],"lq-liqueur-de-chicoree":["Faire sécher les tiges de chicorée et recueillir les fleurs.","Mettre dans un bocal l’alcool⟦I1⟧, les fleurs⟦I0⟧, les clous de girofle⟦I3⟧ et le sucre dissous⟦I4⟧ dans l’eau⟦I2⟧.","Laisser macérer 2 mois en remuant de temps en temps.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-citron":["Rincer et essuyer les citrons⟦I3⟧.","Prélever les zestes avec un épluche-légumes, en évitant d'entamer la peau blanche.","Couper les zestes en fines lanières et les mettre dans une bonbonne avec l'alcool⟦I0⟧.","Couvrir et laisser macérer 2 mois.","Mélanger l'eau et le sucre⟦I2⟧⟦I1⟧ puis porter à ébullition, faire bouillir 1 min puis laisser refroidir ce sirop.","Filtrer l'eau-de-vie et mélanger-la au sirop refroidi.","Mettre en bouteilles et fermer hermétiquement.","Le mélange obtenu titre alors 45°.","Laisser reposer 2 mois avant consommer.","Degré final de la préparation ≈ 38°."],"lq-liqueur-de-clementines":["Laver les clémentines⟦I0⟧ puis recueillir les zestes avec un économe.","Mettre dan un bocal hermétique les zestes et l’alcool⟦I1⟧.","Laisser macérer pendant 2 mois.","Faire le sirop avec l’eau et le sucre⟦I2⟧⟦I3⟧, le laisser refroidir et le mélanger à la macération.","Laisser de nouveau reposer 1 mois.","Filtrer et mettre en bouteilles.","Cette liqueur très fine se boit frappée."],"lq-liqueur-de-coing":["Frotter les coings⟦I0⟧ sans les peler, puis les râper.","Laisser reposer cette purée une nuit.","Le lendemain exprimer tout le jus, et le mettre à cuire 15 minutes.","Préparer le sirop⟦I1⟧⟦I3⟧ et l’ajouter au jus.","Quand tout est bien refroidi, ajouter l’alcool⟦I2⟧ et mettre la préparation dans un bocal fermant bien avec les amandes amères⟦I4⟧.","Placer dans un endroit tempéré pendant 2 mois.","Remuer régulièrement le mélange.","Filtrer et laisser décanter 2 jours.","Filtrer une seconde fois et mettre en bouteilles.","Ne consommer qu’après quelques semaines."],"lq-liqueur-de-coquelicot":["Faire sécher les pétales au soleil, Dans une jarre mettre l’alcool⟦I1⟧ et la cannelle⟦I2⟧, les pétales de coquelicot⟦I0⟧, puis laisser macérer 4 semaines.","Diluer le sucre⟦I3⟧ dans le litre d’eau⟦I4⟧ et laisser refroidir le sirop.","Ajouter le sirop dans la macération, faire reposer 2 jours.","Filtrer et mettre en bouteilles."],"lq-liqueur-douce-de-coriandre":["Mettre tous les ingrédients⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I6⟧ dans un bocal hermétique et laisser macérer à l’ombre pendant au moins 2 mois.","Faire fondre le sucre⟦I5⟧ dans le vin blanc⟦I0⟧ et laisser reposer une semaine.","Filtrer la macération et la mélanger avec le vin sucré.","Laisser reposer un mois, filtrer le tout et mettre en bouteilles."],"lq-liqueur-de-cumin":["Broyer au mortier les graines de cumin⟦I0⟧, peler les citron⟦I4⟧ pour recueillir les zestes.","Mettre le jus des citrons, les zestes et les graines broyées dans l’alcool⟦I1⟧.","Ajouter le sucre⟦I2⟧ dilué dans le verre d’eau⟦I3⟧.","Faire macérer 4 semaines, puis filtrer et mettre en bouteilles."],"lq-liqueur-de-curacao":["Dissoudre le sucre⟦I0⟧ dans 1 litre d’eau⟦I6⟧, et faire macérer tous les ingrédients⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧ pendant 1mois.","Filtrer et mettre en bouteilles.","Si la préparation n’est pas assez colorée on le faire avec du caramel et un peu de carmin."],"lq-liqueur-de-cynorrhodon-gratte-cul":["Le cynorrhodon⟦I1⟧ doit être cueilli bien mûr après les premiers froids.","Couper les fruits en quartiers, les recouvrir d’alcool⟦I0⟧, ajouter le sucre candi⟦I2⟧ et la vanille⟦I3⟧.","Agiter régulièrement le bocal et laisser macérer au moins 3 mois.","Filtrer et presser puis mettre en bouteilles, laisser reposer encore quelques mois à l’ombre d’une cave."],"lq-liqueur-de-figues":["Couper la queue des fruits⟦I3⟧ et les partager en deux.","Les laisser macérer 48 h dans un grand saladier avec la gousse de vanille⟦I4⟧ coupée en 2.","Couvrir d’alcool⟦I0⟧ et mettre la préparation dans un grand bocal hermétique pendant 6 semaines.","Après ce temps la liqueur s’et tintée d’un beau rose clair.","Flirter une première fois pour filtrer les fruits, laisser reposer quelques jours, puis filtrer finement une seconde fois et mettre en bouteilles."],"lq-liqueur-de-fraises":["Laver et équeuter les fraises⟦I1⟧ et les couper en quarts.","Laisser bien sécher les fraises.","Placer les fraises dans un bocal qui peut se fermer hermétiquement.","Ajouter les zestes de citron⟦I5⟧, la vanille fendue⟦I3⟧ et la cannelle⟦I4⟧.","Recouvrir le tout avec l’alcool⟦I0⟧.","Fermer le bocal et laisser macérer pendant 50 jours.","Remuer le mélanger tous les 3 jours.","Après 50 jours, écraser les fruits dans le bocal.","Laisser encore macérer 5 jours.","Au bout des 5 jours, ajouter tout le sucre⟦I2⟧ dilué dans un verre d’eau et laisser encore macérer 2 jours.","Au bout des 2 jours, embouteiller le liquide en le filtrant finement au moins 3 fois.","Servir frais après 1 mois de bouteille."],"lq-liqueur-de-fraises-a-la-cannelle":["Laver et équeuter les fraises⟦I1⟧ et couper en quarts.","Laisser bien sécher les fraises.","Placer les fraises dans un bocal qui peut se fermer hermétiquement.","Ajouter la cannelle⟦I3⟧ et recouvrir le tout avec l’alcool⟦I0⟧.","Fermer le bocal et laisser macérer pendant 50 jours.","Remuer le mélange tous les 3 jours.","Après 50 jours, écraser les fruits dans le bocal Laisser encore macérer 5 jours.","Au bout des 5 jours, ajouter tout le sucre⟦I2⟧ et laisser encore macérer 2 jours.","Au bout des 2 jours, embouteiller le liquide en le filtrant 3 fois.","Servir au bout d’un mois d’embouteillage."],"lq-liqueur-douce-de-fraises-a-la-vanille":["Laver et équeuter les fraises⟦I0⟧.","Sécher les fraises et couper les en petits morceaux.","Mélanger dans un récipient hermétique non transparent les fraises⟦I0⟧, l’alcool⟦I2⟧, l’eau⟦I1⟧, le sucre⟦I3⟧ et la gousse de vanille fendue⟦I4⟧, il faut racler toutes les graines et les mettre dans la bonbonne.","Laisser macérer pendant 3 semaines en remuant le mélange 1 fois par jour.","Au bout des 3 semaines, embouteiller en filtrant le mélange.","Attendre à nouveau 3 semaines avant de servir."],"lq-liqueur-de-framboises":["Ecraser les framboises⟦I0⟧ à travers un tamis fin puis ensuite filtrer le jus dans une passoire très fine.","Verser le jus des framboises dans une jarre.","Ajouter le sucre⟦I2⟧, l'eau de vie de fruits⟦I1⟧, les clous de girofle⟦I3⟧ et la vanille fendue en deux⟦I4⟧.","Fermer le bocal et laisser reposer dans un endroit frais et obscur, pendant 20 jours minimum, en remuant de temps en temps.","Laisser reposer encore 1 ou 2 mois dans l'obscurité avant de consommer."],"lq-liqueur-de-genievre":["Faire une décoction avec l’eau⟦I2⟧ et le genièvre⟦I0⟧, puis dans le liquide encore chaud, dissoudre le sucre⟦I3⟧.","Laisser refroidir et ajouter l’alcool⟦I1⟧.","Laisser reposer dans une jarre au moins 8 semaines.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-girofle-frais":["Dissoudre le sucre⟦I4⟧ dans le verre d’eau⟦I3⟧ et laisser refroidir.","Broyer au mortier les clous de girofle⟦I1⟧.","Mettre à macérer l’alcool⟦I2⟧, le sirop, les clous de girofle et le zeste des oranges⟦I0⟧.","Faire reposer au frais la jarre au moins un mois.","Filtrer finement et mettre en bouteilles."],"lq-liqueur-de-gingembre":["Peler le gingembre⟦I1⟧ et le couper en petits morceaux.","Le faire bouillir à petit feu pendant 30 minutes dans le ½ litre d’eau⟦I3⟧.","Faire dissoudre le sucre⟦I2⟧.","Laisser refroidir puis ajouter cette décoction dans l’alcool⟦I0⟧.","Laisser macérer 4 semaines.","Puis filtrer et mettre en bouteilles.","On peu ajouter une dose de safran⟦I4⟧ pour bien colorer le mélange."],"lq-liqueur-de-graines-de-fenouil-1":["Broyer les épices⟦I2⟧⟦I3⟧⟦I4⟧ puis les faire le sirop de sucre⟦I1⟧, laissez le refroidir et faire macérer tous les ingrédients pendant un mois.","Remuer régulièrement le mélange.","Passé ce délai filtrer la macération et mettre en bouteilles.","Laisser vieillir quelques semaines avant de déguster."],"lq-liqueur-de-graines-de-fenouil-2":["Broyer au mortier les graines d’anis⟦I1⟧ et de fenouil⟦I0⟧ et les faire macérer 4 semaines dans l’alcool⟦I2⟧.","Dissoudre le sucre⟦I3⟧ dans l’eau⟦I4⟧ et l’ajouter à la préparation.","Bien mélanger et laisser reposer 4 semaines.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-groseilles":["Egrapper les groseilles⟦I0⟧, les laver et les sécher.","Les mettre dans un bocal et les recouvrir avec l’alcool⟦I1⟧.","Laisser macérer à l’ombre pendant 2 mois.","Filtrer la préparation et bien exprimer tout le jus à travers une mousseline.","Faire le sirop⟦I3⟧⟦I2⟧ et le laisser bouillir 15 minutes pour le faire légèrement épaissir.","Après refroidissement complet mélanger le sirop à l’alcool, laisser décanter, filtrer et mettre en bouteilles."],"lq-liqueur-de-jasmin":["Effeuiller les fleurs⟦I0⟧ pour ne garder que les pétales, les mettre à macérer dans un bocal hermétique avec l’eau de vie⟦I1⟧. 6 heures après préparer le sirop avec l’eau⟦I3⟧ et le sucre⟦I2⟧ et le verser encore tiède sur la macération.","Laisser reposer 6 jours en remuant de temps en temps.","Passer la liqueur et la mettre en bouteilles.","Attendre quelques semaines avant de consommer cette liqueur très parfumée."],"lq-liqueur-de-kaki":["Ouvrir la gousse de vanille⟦I3⟧, peler les kakis⟦I0⟧ et ne récupérer que la pulpe.","Faire dissoudre le sucre⟦I2⟧ dans l’eau⟦I4⟧ avec la gousse de vanille, puis laisser refroidir.","Mélanger dans une jarre, le sirop avec la vanille et les fruits.","Laisser macérer 8 semaines, puis filtrer et mettre en bouteilles."],"lq-liqueur-de-laitue":["Laver et bien essorer les salades⟦I0⟧⟦I1⟧ puis les mettre dans l’alcool⟦I2⟧.","Faire un sirop avec le sucre⟦I3⟧ et l’eau et sitôt refroidi le mélanger à la macération.","Poser la jarre dans un placard sombre et agiter régulièrement le contenu.","Filtrer au bout de 4 à 5 semaines et mettre en bouteilles."],"lq-liqueur-de-laurier":["Hacher grossièrement les feuilles⟦I0⟧ et le mettre dans l’alcool⟦I1⟧.","Faire un sirop avec l’eau⟦I2⟧ et le sucre et laisser refroidir.","Mélanger le tout dans une jarre, puis laisser reposer 8 semaines.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-lait":["Faire bouillir le lait⟦I0⟧ avec la gousse de vanille fendue⟦I3⟧, racler bien toutes les graines.","Laisser refroidir et ajouter l’alcool⟦I1⟧ les zestes de citron⟦I2⟧ et le sucre de canne⟦I4⟧.","Laisser macérer 15 jours, filtrer et mettre en bouteilles.","Se consomme très frais."],"lq-liqueur-de-magnolia":["Découper finement les pétales des fleurs de magnolia⟦I0⟧.","Les mettre dans un bocal hermétique avec la vanille fendue⟦I1⟧ et le sucre⟦I2⟧.","Arroser avec le vin⟦I3⟧ et ajouter l’eau de vie⟦I4⟧.","Remuer et fermer le bocal.","Laisser 4 semaines dans un endroit frais et à l’ombre.","Agiter régulièrement la préparation.","Passer en exprimant la macération, mettre en bouteilles, se consomme immédiatement."],"lq-liqueur-de-caramel":["Faire doucement fondre le caramel⟦I0⟧ dans l’eau⟦I1⟧ avec la vanille⟦I2⟧ fendue.","Laisser refroidir puis mettre ce sirop et l’alcool⟦I3⟧ dans une jarre et bien dissoudre le tout.","Laisser reposer 10 jours et mettre en bouteilles."],"lq-liqueur-de-mandarine":["Laver les mandarines⟦I2⟧, prélever les zestes.","Presser leur jus.","Le verser dans un bocal avec les zestes et le rhum⟦I0⟧.","Laisser macérer 2 mois.","Faire fondre le sucre⟦I1⟧ dans un peu d'eau⟦I3⟧ et mélanger à l'alcool de mandarines filtré.","Mettre en bouteilles et attendre 30 jours avant de déguster."],"lq-liqueur-de-manzana":["Dissoudre le sucre⟦I2⟧ dans le jus de pommes⟦I1⟧, chauffer le mélange autour de 60°C pour finir de dissoudre le sucre.","Ensuite, mélanger avec l'eau de vie⟦I0⟧ à parts égales.","On peut mettre un peu plus de jus que d'eau de vie pour avoir une liqueur plus soft.","Une semaine plus tard, filtrer le jus pour en sortir les impuretés.","Le mettre en bouteille et filtrer finement plusieurs fois, puis laisser reposer de longs mois.","Six mois sont raisonnables."],"lq-liqueur-de-melisse":["Mettre à macérer pendant un mois tous les ingrédients sauf le sucre⟦I5⟧ et l’eau⟦I6⟧.","Passé ce délai faire le sirop avec le sucre et l’eau et le mélanger tiède à la préparation.","Laisser reposer 15 jours, puis filtrer et mettre en bouteilles.","Pendant la macération laisser le bocal dans un endroit sombre."],"lq-liqueur-de-melon":["Peler le melon⟦I0⟧ et supprimer les pépins.","Couper la pulpe en petits cubes et mettre à macérer dans l’alcool⟦I1⟧ pendant un mois.","Faire un sirop avec l’eau⟦I3⟧ et le sucre⟦I2⟧ et mélanger à la préparation.","Laisser confire pendant 2 mois.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-menthe-1":["Effeuillez le bouquet de menthe⟦I0⟧ en éliminant les tiges.","Mettez les feuilles dans un bocal préalablement ébouillanté et séché, recouvrez d'eau de vie⟦I1⟧.","Fermez et laissez macérer 2 semaines.","Au bout de ce temps, portez 12 cl d'eau⟦I4⟧ à ébullition dans un faitout, avec le sucre⟦I2⟧.","Faites bouillir 1 minute puis laissez refroidir ce sirop.","Râpez finement le zeste du demi-citron⟦I3⟧, ajoutez-le dans le bocal, ainsi que le sirop refroidi.","Fermez à nouveau et laissez macérer 3 semaines à l’ombre.","Filtrez à travers une passoire doublée d'une étamine, mettez en flacons, bouchez hermétiquement.","Laissez reposer 2 mois avant de consommer."],"lq-liqueur-de-menthe-2":["Lavez les feuilles de menthe⟦I0⟧, égouttez-les et séchez-les.","Mettre les feuilles de menthe dans un bocal avec l'alcool⟦I1⟧, fermez hermétiquement et faire macérer pendant une semaine au soleil si possible.","Faire un sirop de sucre⟦I2⟧ léger (1 minute d'ébullition).","Filtrez l'alcool et ajoutez le sirop de sucre.","Colorez avec le sirop de menthe⟦I4⟧ et mettre en bouteille."],"lq-liqueur-de-menthe-3":["Lavez les feuilles de menthe⟦I0⟧, égouttez-les et séchez-les.","Mettre les feuilles de menthe dans un bocal avec l'alcool⟦I2⟧, fermez hermétiquement et faire macérer pendant un mois au soleil si possible.","Préparez un sirop de sucre⟦I1⟧.","Filtrez l'alcool et ajouter le sirop de sucre.","Préparez un caramel très brun et ajoutez quelques gouttes de citron⟦I5⟧.","Versez ce caramel dans la liqueur et mettez en bouteilles."],"lq-liqueur-de-millepertuis":["Mettre les fleurs⟦I1⟧ et le citron⟦I2⟧ coupé en tranches fines dans l’alcool⟦I0⟧.","Faire macérer au moins 6 semaines au soleil.","Filtrer la préparation et ajouter le sirop froid.","Laisser reposer quelques jours, filtrer à nouveau et mettre en bouteilles.","Il faut faire vieillir 2 à 3 mois avant de déguster cette liqueur rouge."],"lq-liqueur-de-mirabelles-au-rhum":["Laver et dénoyauter les mirabelles⟦I0⟧.","Plonger quelques secondes les mirabelles dans l’eau⟦I3⟧ bouillante afin d’éviter une fermentation en bouteille.","Placer les mirabelles dans une bouteille et compléter avec le rhum⟦I1⟧.","Casser les noyaux des mirabelles et les ajouter à la préparation.","Laisser macérer 2 mois.","Au bout des 2 mois, filtrer finement et embouteiller.","Attendre encore 4 semaines avant de servir."],"lq-liqueur-de-mure":["Faire mariner les mûres⟦I0⟧ légèrement écrasées et l'alcool⟦I2⟧ dans un bocal hermétique pendant 6 semaines.","Tamiser la préparation en la passant à travers un linge et presser les baies.","Dans une casserole, porter l'eau⟦I3⟧ à ébullition avec le sucre⟦I1⟧, et mélanger le sirop à l'alcool.","Mettre en bouteilles et à consommer après 4 mois.","Le goût du fruit est parfaitement conservé, se bois bien frais avec un glaçon ou après avoir mis la bouteille et les verres au congélateur."],"lq-liqueur-de-myrte":["Faire macérer la plante⟦I0⟧, la cannelle⟦I2⟧ et la vanille⟦I3⟧ dans l'alcool⟦I1⟧ pendant 3 semaines à 1 mois.","Filtrer, ajouter le sucre⟦I4⟧ mouillé avec le verre d'eau⟦I5⟧.","Mélanger et mettre en bouteilles.","Laisser vieillir au frais et à l’ombre."],"lq-liqueur-de-myrtille":["Laver les myrtilles⟦I0⟧ et les égoutter.","Les faire macérer avec la cannelle⟦I2⟧ dans l'eau-de-vie⟦I1⟧ pendant 2 mois.","Passé ce temps faire un sirop de sucre⟦I3⟧.","Filtrer l'alcool et mélanger avec le sirop laisser reposer quelques jours.","Re-filtrer finement et verser dans des bouteilles et bien boucher."],"lq-liqueur-de-nefles":["Mettre dans un bocal les noyaux de nèfles⟦I0⟧ avec l'alcool⟦I1⟧.","Laisser macérer 1 mois.","Préparer un sirop de sucre⟦I2⟧ et mélanger à l'alcool.","Filtrer et mettre en bouteilles."],"lq-liqueur-de-noisette-au-whisky":["Martelez les noisettes⟦I0⟧ pour les briser mais ne perdez pas le jus, mettre le tout dans un bocal avec l'eau⟦I2⟧ et le whisky⟦I1⟧.","Fermez hermétiquement.","Laissez macérer 2 longs mois, voir plus.","Filtrer à travers une passoire et remettez le liquide dans un bocal avec le miel⟦I4⟧, la gousse de vanille⟦I3⟧ et le sucre⟦I5⟧ en sirop.","Laissez reposer encore un mois.","Retirer la gousse de vanille et laisser décanter.","Mettre en bouteilles."],"lq-liqueur-de-noix":["Dans un bocal mettre les noix⟦I0⟧ coupées en 4.","Ajouter les autres ingrédients et les épices, sauf l'eau⟦I6⟧.","Fermer le bocal et laisser reposer 40 jours en agitant de temps en temps.","Filtrer la préparation, ajouter l'eau bouillie et sucrée bien refroidie, laisser reposer quelques jours en remuant quelques fois, puis filtrer finement et mettre en bouteilles.","Attendre 6 semaines avant de déguster, voir plus."],"lq-liqueur-de-noyaux-d-abricots":["Casser les noyaux⟦I0⟧ afin de prélever les amandes.","Ebouillanter ces amandes, retirer la peau et hacher les.","Broyer les coques.","Mettre amandes et coques dans un bocal avec l'eau-de-vie⟦I1⟧.","Les clous de girofle⟦I3⟧ et la cannelle⟦I4⟧.","Laisser macérer 8 semaines.","Au bout de ce temps, préparer un sirop de sucre⟦I2⟧.","Filtrer et mélanger longuement avec le sirop de sucre.","Mettre en bouteilles et laisser reposer 8 semaines avant consommation."],"lq-liqueur-de-noyaux-d-abricots-aux-epices":["Piler au mortier toutes les épices⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧, fendre la vanille⟦I8⟧ et la couper en tronçons.","Fondre le sucre⟦I2⟧ dans l’eau⟦I3⟧ et laisser refroidir.","Casser tous les noyaux⟦I0⟧ et conserver la coque et les amendes.","Dans une jarre mettre les épices, le sirop, l’alcool⟦I1⟧ et les noyaux concassés.","Faire macérer dans une jarre hermétique pendant 2 mois.","Filtrer finement et mettre en bouteilles."],"lq-liqueur-de-noyaux-de-peches":["Pendant tout l’été."],"lq-liqueur-de-pissenlit":["Faire macérer dans l'eau de vie⟦I1⟧ pendant deux semaines les fleurs⟦I0⟧ et le zeste⟦I2⟧.","Filtrer, ajouter le sucre⟦I3⟧ mouillé avec l'eau⟦I4⟧ et mettre en bouteilles pour conserver au frais."],"lq-liqueur-de-poire":["Mettre la poire⟦I0⟧ et l'eau-de-vie⟦I1⟧ ordinaire dans un bocal.","Placer le bocal pendant 1 mois le plus souvent possible au soleil.","Ajouter le sucre⟦I2⟧ dissous dans l’eau⟦I3⟧ et laisser reposer environ 3 mois.","Mettre en bouteille."],"lq-liqueur-de-primeveres":["Faire chauffer l’eau⟦I6⟧ et dissoudre le sucre⟦I4⟧, plonger les différentes fleurs⟦I0⟧⟦I1⟧⟦I2⟧, la gousse de vanille⟦I5⟧ fendue, donner quelques bouillons et laisser refroidir.","Mettre le sirop et les fleurs dans une jarre, ajouter l’alcool⟦I3⟧ et laisser macérer à l’ombre 4 semaines.","Filtrer et mettre en bouteilles après décantation."],"lq-liqueur-de-prunelles":["Laver et essuyer les fruits⟦I3⟧ ramassée après les premières gelées.","Écraser les dans une casserole sans les dénoyauter puis faites les bouillir dans le pendant 15 mn.","Laisser reposer avec la cannelle⟦I4⟧ pendant 3 jours la purée dans un bocal hermétiquement fermé.","Filtrer le tout avec une passoire.","Verser le jus avec le sucre⟦I1⟧ dans une casserole et faites bouillir à petit feu pendant 5 mn en remuant.","Laisser refroidir puis ajouter l'alcool⟦I0⟧.","Remettre la préparation dans un bocal hermétiquement fermé et laisser reposer 1 semaine.","Filtrer avec un filtre en papier et mettre en bouteilles.","Laisser reposer dans un endroit frais et sombre pendant 3 mois."],"lq-liqueur-de-prunes":["Laver et essuyer les fruits⟦I0⟧.","Ecraser les fruits sans les dénoyauter.","Mettre les fruits dans une casserole, ajouter le vin⟦I3⟧ et faire bouillir à tout petit bouillon pendant 15 min.","Mettre cette marmelade dans un bocal hermétique avec le bâton de cannelle⟦I4⟧.","Laisser reposer cette marmelade pendant 3 jours dans un endroit sombre.","Au bout de 3 jours, filtrer la marmelade avec une passoire pour récupérer le jus.","Faire réduire à petit feu le jus récupéré avec le sucre⟦I1⟧ dans une casserole pendant 5 minutes.","Bien mélanger pendant la réduction.","Laisser refroidir, remettre ce jus dans un bocal hermétique et ajouter l’alcool⟦I2⟧.","Laisser reposer 1 semaine dans un endroit sombre.","Au bout d’une semaine, embouteiller le mélange en filtrant.","Laisser reposer 3 mois dans un endroit sombre avant de servir."],"lq-liqueur-de-raisin":["Laver, sécher les raisins⟦I1⟧, puis les écraser et les mettre sur petit feu jusqu'à ébullition.","Conserver l'ébullition à feu doux pendant 10 min.","Laisser refroidir et passer au tamis.","Rajouter l'alcool⟦I0⟧, le sucre⟦I1⟧, les clous de girofle⟦I3⟧ et le bâton de cannelle⟦I2⟧, mélanger.","Laisser macérer un mois.","Filtrer et mettre en bouteilles.","Se consomme bien frais."],"lq-liqueur-de-reglisse":["Couper en tronçons la réglisse⟦I1⟧ et la mettre à macérer dans l’alcool⟦I2⟧ avec la menthe⟦I0⟧.","Ajouter la vanille⟦I5⟧ fendue et le sucre⟦I3⟧ dissous dans le verre d’eau⟦I4⟧.","Mettre la jarre dans un passage et la remuer régulièrement.","Au de 2 mois, filtrer finement et mettre en bouteilles."],"lq-liqueur-de-rhubarbe":["Laver les tiges de rhubarbe⟦I2⟧ et les détailler en tronçons.","Mettre dans une jarre la rhubarbe, les gousses de cardamome⟦I3⟧ écrasées recouvrir avec l’alcool⟦I0⟧.","Fermer hermétiquement le bocal et le laisser exposé au soleil 4 semaines.","Faire un sirop avec l’eau⟦I4⟧ et le sucre⟦I1⟧ puis l’incorporer froid à la macération.","Prolonger 2 semaines de plus au soleil, filtrer et mettre en bouteilles."],"lq-liqueur-de-rhum-au-cafe":["Verser le rhum⟦I0⟧ dans un grande bouteille ou une bonbonnière en verre.","Fendre les gousses de vanilles⟦I1⟧ dans le sens de la longueur.","Ajouter les gousses de vanilles, le sucre de canne⟦I3⟧, les grains de café⟦I2⟧ et bien mélanger le tout.","Conserver 4 mois à l’abri de la lumière et prenant soin de remuer le mélange toutes les semaines.","Filtrer avant de mettre en bouteille."],"lq-liqueur-de-romarin":["Faire un sirop et le laisser refroidir.","Mélanger les fleurs⟦I3⟧, le sirop et l’alcool⟦I0⟧.","Faire macérer 2 mois à l’ombre.","Passé ce délai filtrer la préparation, laisser décanter quelques jours, filtrer à nouveau et mettre en bouteilles.","Laisser vieillir avant de consommer."],"lq-liqueur-de-roses":["Dans un bocal, poser les pétales de roses⟦I0⟧ en alternant avec le sucre⟦I1⟧.","Couvrir le bocal et laisser macérer une nuit.","Verser l'eau⟦I3⟧ sur la préparation pour faire dissoudre le sucre.","Agiter le bocal, laisser reposer une journée puis filtrer le jus.","Mélanger celui-ci avec l'alcool⟦I2⟧.","Verser la liqueur parfumée dans le bocal qui a servi à la macération.","Fermer et laisser reposer 6 semaines avant de filtrer et mettre en bouteilles."],"lq-liqueur-de-sauge":["Mettre la sauge⟦I3⟧ avec les 3 clous de girofle⟦I5⟧ et les zestes des citrons⟦I4⟧ dans un bocal.","Ajouter l'alcool⟦I0⟧.","Laisser macérer pendant un mois en remuant de temps en temps.","Préparer un sirop de sucre⟦I2⟧ à froid, mélanger avec l'alcool.","Laisser reposer une semaine.","Filtrer et mettre en bouteilles.","Conserver au frais."],"lq-liqueur-de-sommeil-xvie-siecle":["Dans une jarre mettre les plantes⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ broyées au mortier à macérer dans l’alcool⟦I5⟧ dans lequel aura dissous le miel⟦I6⟧.","Laisser agir à l’ombre durant 3 mois puis passer au clair plusieurs fois au besoin.","Mettre en bouteilles et laisser vieillir quelques mois.","Quelques gouttes versées dans une tisane de tilleul ou verveine vous assurera une nuit calme et paisible."],"lq-liqueur-de-baies-de-sureau":["Mettre dans une casserole les baies de sureau⟦I0⟧ mûres et bien noires après les avoir rincées, le sucre⟦I3⟧ la vanille⟦I4⟧ fendue et l’eau⟦I2⟧.","Cuire à petit bouillon pendant 15 minutes pour faire éclater les fruits.","Puis laisser complètement refroidir.","Dans une jarre mélanger la préparation de sureau avec l’alcool⟦I1⟧ et laisser reposer à l’ombre au moins 2 mois.","Ecraser au chinois la macération puis filtrer finement et mettre en bouteilles."],"lq-liqueur-de-the":["Mettez le thé⟦I0⟧ dans une théière, versez dessus l'eau bouillante⟦I3⟧, remuez, couvrez et laissez infuser 3 minutes.","Après cela, filtrez le thé, faites le macérer avec le sucre⟦I2⟧, puis après refroidissement l'eau de vie⟦I1⟧ et la cannelle⟦I4⟧.","Verser la macération dans un bocal pendant 3 semaines.","Filtrer soigneusement pour mettre en bouteilles.","Plus elle vieillira (5-6 mois au moins), meilleure elle sera."],"lq-liqueur-de-the-aux-epices":["Infuser le thé⟦I3⟧ dans de l’eau⟦I1⟧ chaude, ajouter le sucre⟦I2⟧ et laisser refroidir.","Mettre alors cette infusion avec les feuilles dans une jarre et ajouter tous les autres ingrédients⟦I0⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧ et la vanille⟦I8⟧ fendue.","Laisser au repos 4 semaines, puis filtrer et mettre en bouteilles.","C’est une liqueur très douce et bien parfumée."],"lq-liqueur-de-thym":["Faire macérer le thym⟦I0⟧ et les fleurs⟦I1⟧ dans l'eau-de-vie⟦I2⟧ pendant 2 semaines.","Filtrer et ajouter le miel⟦I3⟧.","Bien mélanger laisser reposer et mettre en bouteilles.","Faire vieillir au frais pendant 3 mois avant de déguster."],"lq-liqueur-de-tilleul":["Faire macérer le tilleul⟦I1⟧ pendant 2 mois dans l’alcool⟦I0⟧.","Filtrer puis faire le sirop⟦I2⟧⟦I3⟧ et le mélanger à la macération.","Laisser reposer quelques jours puis filtrer et mettre en bouteilles.","Cet alcool sera meilleur après l’avoir laissé vieillir quelques mois."],"lq-liqueur-de-tournesol":["Effeuiller les pétales de⟦I0⟧ tournesol⟦I1⟧ au dessus de l’alcool⟦I4⟧.","Faire un sirop avec l’eau⟦I3⟧ et le sucre⟦I2⟧.","Dans une jarre ajouter le sirop, l’alcool avec les pétales et la gousse de vanille⟦I5⟧ fendue.","Laisser dans un coin sombre au moins 2 mois.","Filtrer finement et mettre en bouteilles."],"lq-liqueur-de-vanille-au-rhum-blanc":["Fendre les gousses de vanille⟦I0⟧ dans le sens de la longueur, puis les couper en petits morceaux, en prenant soin de ne pas perdre les petites graines noires qui renferment tout le parfum.","Mettez la vanille dans un bocal préalablement ébouillanté et séché, recouvrez de rhum⟦I1⟧.","Fermez et laissez macérer 8 jours, en agitant le bocal chaque jour.","Filtrez le rhum parfumé, mélangez-y le sirop de canne⟦I2⟧.","Mettez en flacon, bouchez hermétiquement.","Patientez encore 8 jours avant de consommer.","Idéal un soir d’été avec une glace à la vanille."],"lq-liqueur-de-vanille":["Faire macérer dans l’alcool⟦I0⟧ à 40°, 6 gousses de vanille⟦I1⟧ que vous aurez fendues.","Il faut bien racler les graines et le mettre également dans l’alcool.","Laissez infuser la vanille coupée par le milieu et en long pendant 20 jours.","Dissoudre le sucre⟦I3⟧ dans l’eau⟦I2⟧ et ajoutez ce sirop froid à la préparation.","Filtrer finement et mettre en bouteilles."],"lq-liqueur-verte-de-citronnelle":["Dissoudre le sucre⟦I4⟧ dans le verre d’eau⟦I5⟧ en portant à ébullition.","Mettre à infuser dans le sirop, les herbes⟦I2⟧⟦I3⟧, le zeste et le jus du citron⟦I0⟧.","Arrêter au premier bouillon et laisser refroidir.","Ajouter l’alcool⟦I1⟧ et laisser macérer 4 semaines à l’ombre.","Filtrer et mettre en bouteille."],"lq-liqueur-de-venus-xvii-siecle":["Faire macérer les ingrédients⟦I0⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧ pendant 4 semaines.","Filtrer.","Préparer le sirop de sucre⟦I1⟧ avec les 400 g et ajouter-le à la préparation.","Filtrer et mettre en bouteille.","Ne pas consommer avant 3 mois."],"lq-liqueur-de-verveine":["Lavez les feuilles⟦I0⟧ et séchez-les dans un torchon.","Les mettre dans un bocal et les recouvrir avec l'eau-de-vie⟦I2⟧.","Fermez hermétiquement et laissez macérer pendant 8 semaines.","Au bout de ce temps, passez puis reversez-le dans le bocal.","Laissez reposer pendant quelques heures.","Faire dissoudre le sucre⟦I1⟧ dans l’eau⟦I3⟧ puis laisser refroidir le sirop.","Ajoutez le sirop et mélanger.","Laissez reposer, en remuant de temps en temps, jusqu'à ce que le sucre soit complètement dissous.","Filtrez finement et mettre en bouteilles."],"lq-liqueur-de-vespetro-xviii-siecle":["Mettre tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧ dans une gaze, faire fondre le sucre⟦I4⟧ dans très peu d’eau⟦I6⟧.","Mélanger le sirop et l’alcool⟦I5⟧, laisser infuser les aromates deux mois dans la bonbonne, filtrer finement décanter et mettre en bouteilles."],"lq-liqueur-de-vieux-garcon":["Mettre les fruits⟦I0⟧ dans un grand pot en grès ou une jarre dans lequel laisser macérer le mélange.","Ce récipient devra pouvoir contenir plusieurs kilos de fruits.","Fermer le pot après chaque ajout de fruit, veiller à ce que l’alcool⟦I11⟧ recouvre bien tout pour ne pas moisir.","Après l’ajout des derniers fruits laisser macérer 1 mois.","Passer finement le mélange et presser les fruits.","Mettre en bouteilles et laisser reposer quelques semaines."],"lq-liqueur-de-violettes":["Faire un sirop avec l'eau⟦I3⟧ et le sucre⟦I2⟧, le laisser refroidir.","Enlever tiges et étamines des fleurs⟦I0⟧, il restera les pétales que l'on met à infuser dans L'alcool⟦I1⟧ pendant 10 jours.","Filtrer et mélanger ce liquide parfumé au sirop.","Mettre en flacons et fermer."],"lq-liqueur-de-zestes-d-agrumes":["Acheter des fruits non traités, les laver, les essuyer, les zester avec un couteau économe pour ne garder que la partie colorée.","Mettre ces zestes⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ à macérer dans l'eau-de-vie⟦I0⟧ pendant 60 jours.","Faire un sirop de sucre⟦I5⟧ et laisser tiédir.","Joindre au sirop la préparation passée et filtrée.","Mettre en bouteilles.","Attendre 2 mois avant de servir."],"lq-liqueur-d-eau-de-fleur-d-oranger":["Dissoudre le sucre⟦I2⟧ dans l’eau de fleur d’oranger⟦I1⟧, puis y ajouter l’eau-de-vie⟦I0⟧, mettre en bouteilles, boucher et laisser reposer un mois avant de servir.","Cette liqueur très simple s’améliore en vieillissant quelques mois."],"lq-liqueur-d-estragon":["Lavez les branches d'estragon⟦I1⟧ et séchez-les parfaitement.","Mettez-les dans un bocal avec l'eau de vie⟦I2⟧.","Bouchez hermétiquement.","Laissez macérer 4 jours, retirez l'estragon et ajoutez le sirop de sucre⟦I3⟧.","Faire macérer encore 1 mois, jusqu'à ce que le sucre soit fondu.","Filtrer finement laisser décanter et mettre en flacon.","Cette liqueur est prête à la dégustation."],"lq-liqueur-d-eucalyptus":["Faire macérer pendant 1 mois dans l’alcool⟦I0⟧, les feuilles d’eucalyptus⟦I3⟧ et la cannelle⟦I4⟧.","Remuer quelques fois la préparation, puis faire un sirop avec l’eau⟦I1⟧ et le sucre⟦I2⟧, et l’ajouter dans la macération.","Laisser reposer 2 semaines, filtrer et mettre en bouteilles."],"lq-liqueur-d-hysope":["Faire un sirop avec l’eau⟦I2⟧ et le sucre⟦I1⟧, mélanger l’alcool⟦I0⟧ et l’hysope⟦I3⟧, ajouter le sirop froid et laisser macérer à l’ombre pendant au moins 2 mois.","Filtrer et laisser reposer quelques jours.","Filtrer de nouveau laisser décanter et mettre en bouteilles.","Faire vieillir quelques mois avant de consommer."],"lq-liqueur-d-or":["Dans une jarre, mettre les épices concassés⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧⟦I8⟧⟦I9⟧ recouvrir avec l’eau-de-vie⟦I0⟧, fermer hermétiquement et laisser macérer 30 jours en remuant souvent.","Faire un sirop avec le sucre⟦I10⟧ et le verre d’eau⟦I11⟧, l’ajouter froid à la macération.","Remuer, laisser reposer 24 heures.","Passer, décanter et filtrer, mettre en bouteille en verre blanc et froisser dedans la feuille d’or⟦I12⟧, pour la réduire en fragments.","Boucher et laisser reposer 30 jours.","Avant de servir, remuer le flacon, pour que les fragments d’or volent et scintillent, et que chacun puisse avoir de l’or dans son verre."],"lq-liqueur-d-orange-ou-cointreau-maison":["Verser l'alcool⟦I1⟧ dans un bocal.","Passer une ficelle autour de l'orange⟦I0⟧ pour faire une sorte de filet qui permettra de la suspendre.","Il suffit de faire une croix comme pour emballer un paquet.","Suspendre l'orange de telle sorte qu'elle soit au dessus de l'alcool à 1 cm max et sans le toucher, puis nouer la ficelle autour du bocal.","Piquer l’orange de quelques coups de pointe de couteau et faire un sirop avec le sucre⟦I2⟧ et l'eau⟦I3⟧.","Porter à ébullition en tournant le mélange avec une cuillère de bois.","Mélanger le sirop froid à l'alcool, et refermer hermétiquement le bocal.","Oublier le bocal à l’ombre au moins 3 mois puis filtrer le tout et mettre l'alcool en bouteille."],"lq-liqueur-d-orange-au-sirop-d-erable":["Prélever les zestes des oranges⟦I0⟧, en évitant au maximum de prélever le blanc, puis presser les oranges.","Verser leur jus dans une carafe munie d'un bouchon et ajouter les zestes le sirop d'érable⟦I1⟧, la cannelle⟦I3⟧, les clous de girofle⟦I4⟧.","Laisser macérer 2 mois au frais.","Filtrer la liqueur et mettre en bouteille.","Conserver au réfrigérateur."],"lq-liqueur-du-pendu-a-l-orange":["Piquer l’orange⟦I1⟧ de clous de girofle⟦I2⟧ sans trop les serrer, toute l’orange doit en être couverte.","L’envelopper dans une gaze pour faire comme un sac.","Verser l’alcool⟦I0⟧ et le sucre⟦I3⟧ en poudre dans un bocal suffisamment large pour laisser passer l’orange.","Suspendre l’orange à 1 cm au dessus de l’alcool, fermer hermétiquement, puis oublier le mélange au fond d’un placard au moins 3 mois.","Enlever l’orange puis Filtrer et mettre en bouteilles."],"lq-liqueur-du-pendu-a-la-poire":["Mettre le sucre⟦I2⟧, l'eau-de-vie⟦I1⟧ dans un grand bocal et suspendre la poire⟦I0⟧ au couvercle par un fil sans la plonger dans le liquide.","Dissoudre le sucre dans un verre d’eau⟦I3⟧ et le mélanger refroidi dans l’alcool.","Attendre 10 semaines que la poire se ratatine pour filtrer et mettre en bouteilles.","Se bonifie grandement avec le temps."],"lq-liqueur-noisetine":["Casser les noisettes⟦I0⟧ et écraser le fruit avec sa coque.","Mettre le tout dans un bocal fermant hermétiquement.","Verser l'eau de vie⟦I1⟧.","Fermer et laisser macérer au moins deux mois.","Filtrer l'infusion.","Faire fondre le sucre⟦I2⟧ dans l'eau⟦I3⟧ et laisser refroidir et ajouter à l'infusion.","Mettre dans une jolie bouteille blanche.","Alcool idéal pour parfumer les crèmes et les gâteaux, son goût est très délicat."],"lq-liqueur-persicot":["Briser les noyaux⟦I0⟧ pour récupérer les amandes.","Faire macérer les aromates⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ avec les amandes dans l'alcool⟦I6⟧ pendant une semaine.","Réaliser un sirop de sucre⟦I7⟧.","Filtrer l'alcool et mélanger avec le sirop.","Mettre en bouteilles et laisser vieillir avant dégustation."],"lq-liqueur-prunelline":["lavez les prunelles⟦I0⟧, égouttez-les, retirer les queues et piquez les fruits à l'aide d'un ustensile que vous fabriquerez avec six épingles.","Mettez les prunelles dans un grand bocal ; ajoutez le sucre⟦I3⟧, dissous, les amandes⟦I2⟧ et l'alcool⟦I1⟧.","Fermez hermétiquement et agitez vigoureusement.","Laissez macérer pendant 3 mois dans un endroit frais et à l'abri de la lumière ; remuez le bocal toutes les semaines.","Filtrez alors finement la liqueur laisser décanter et mettre en bouteilles."],"lq-pippermint-maison":["Mélanger, menthe verte + menthe glaciale⟦I0⟧ l’alcool à 40°⟦I1⟧ et l’eau.","Mettre en bouteille.","Peut se consommer immédiatement et très frais."],"lq-shrubb-a-la-clementine-et-a-l-orange":["Prélevez le zeste des oranges⟦I0⟧, pelez les clémentines⟦I1⟧ puis ôtez la peau blanche amère Dans une jarre, introduisez les zestes des agrumes, ajoutez le rhum⟦I2⟧ et la gousse de vanille⟦I4⟧ fendue dans sa longueur complétez avec le sirop de sucre de canne⟦I3⟧ ajoutez le clou de girofle⟦I5⟧ et la cannelle⟦I6⟧.","Fermez et laissez macérer pendant 1 mois.","Filtrez la finement la préparation."],"cr-creme-d-abricots":["Lavez les abricots⟦I0⟧ bien mûrs, ôtez les noyaux.","Faites les cuire peu d'eau, à feu doux pendant 5 minutes.","Passez la pulpe à travers un tamis en l'écrasant avec une cuillère en bois.","Mettez-la dans un bocal avec l'alcool⟦I1⟧ et la cannelle⟦I2⟧.","Casser les noyaux et mettre également les amandes et le bois des noyaux.","Laissez macérer 30 jours.","Mettez dans une casserole le vin⟦I3⟧ et le sucre⟦I4⟧.","Faites tiédir à feu doux, en remuant sans arrêt, jusqu'à ce que le sucre soit fondu.","Laissez refroidir.","Ajoutez au vin sucré le contenu du bocal, laissez reposer 5 jours et filtrer finement.","Décanter et Mettre en bouteilles."],"cr-creme-de-cacao":["dans un bocal hermétique, mélanger tous l’ingrédient⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧ avec la vanille⟦I4⟧ fendue.","Laisser macérer pendant 4 semaine et remuant régulièrement pour ne pas que le cacao se fige.","Passé ce temps filtrer et mettre en bouteilles."],"cr-creme-de-capucines":["Rincer à l’eau courante les fleurs⟦I0⟧ et les feuilles⟦I1⟧, puis les faire bouillir 10 mn à gros bouillon.","Laisser la décoction refroidir, puis passer le liquide dans une jarre et laisser reposer 5 jours au frais.","Filtrer finement le liquide et reporter à ébullition pour y faire dissoudre le miel⟦I5⟧, et le sucre⟦I6⟧.","Rajouter après refroidissement le cidre⟦I3⟧ et l’alcool⟦I2⟧, bien remuer puis filtrer à nouveau, laisser refroidir et mettre en bouteilles."],"cr-creme-de-cafe":["Faire infuser dans l’alcool⟦I1⟧ pendant 20 jours le café moulu⟦I0⟧.","Faire ensuite doucement réchauffer au bain marie pour obtenir une belle infusion de café.","Ajouter le sucre en poudre⟦I2⟧ dissout dans 1 litre d’eau⟦I3⟧ et laisser reposer 15 jours.","Passer la préparation au chinois et mettre en bouteilles.","Laisser vieillir quelques semaines avant de consommer."],"cr-cremino-de-cafe":["Faire infuser dans l’alcool⟦I1⟧ pendant 20 jours le café moulu⟦I0⟧.","Faire ensuite doucement réchauffer au bain marie pour obtenir une belle infusion de café.","Ajouter le sucre en poudre⟦I2⟧ dans le litre de lait entier⟦I3⟧ tiède et le laisser refroidir.","Laisser reposer 15 jours.","Passer la préparation au chinois et mettre en bouteilles.","Laisser vieillir quelques semaines avant de consommer."],"cr-creme-de-cerises":["Ecraser les fruits⟦I0⟧ et les noyaux au mortier et les placer dans un bocal avec la vanille⟦I2⟧.","Recouvrir d’alcool⟦I1⟧.","Boucher le bocal et laisser macérer à température douce pendant 2 mois minimum.","Filtrer et ajouter le sirop⟦I4⟧⟦I3⟧.","Laisser reposer 8 à 10 jours filtrer à nouveau et mettre en bouteilles."],"cr-creme-de-chataignes":["Une partie des châtaignes⟦I4⟧ (environ 250 g) doivent être fraîches, épluchées en laissant la peau de couleur foncée et divisées en quatre.","L´autre portion de la quantité équivalente sera cuite et complètement épluchée avant d´être découpée en quatre.","La préparation se fait comme pour la recette de base en prenant soin de secouer le bocal de temps à autre.","Laisser reposer 5 semaines et passer au tamis."],"cr-creme-de-fraises-des-bois":["Dans un grand faitout, mettre la purée de fruit⟦I0⟧ et le vin⟦I1⟧, couvrir et laisser ainsi pendant 5 jours à température ambiante.","Ajouter le sucre⟦I3⟧ et faire bouillir 3 min en remuant, le sucre doit être bien dissout.","Il sera nécessaire d'écumer un peu.","Quand la crème est refroidie, ajouter l’alcool⟦I4⟧.","Filtrer à la passoire à cause de l’épaisseur du liquide et mettre en bouteilles."],"cr-creme-de-framboises":["Ecrasez et passez au tamis les framboises⟦I0⟧.","Mettez-les dans un récipient et laissez-les décanter une nuit au frais.","Ajoutez aux framboises les 2 litres d’alcool⟦I1⟧ et le sirop de sucre⟦I2⟧ préparé avec l’eau⟦I3⟧.","Mettre toute cette préparation dans une jarre bien bouchée, laisser reposer 4 semaines en remuant régulièrement, puis filtrez et mettez en bouteilles.","Attentez quelques semaines avant de consommer cette liqueur légère en alcool, qui vieillit admirablement."],"cr-creme-de-menthe":["Immerger les feuilles de menthe⟦I0⟧ lavées et séchées dans un bocal contenant l'eau-de-vie⟦I1⟧.","Fermer hermétiquement et laisser macérer 6 semaines.","Porter à ébullition l'eau⟦I2⟧ et le sucre⟦I3⟧, écumer et laisser refroidir.","Mélanger le sirop et l'eau-de-vie de macération puis laisser reposer quelques jours.","Décanter, filtrer finement et mettre en bouteilles."],"cr-creme-de-mures":["Mettre dans un grand saladier les mûre⟦I0⟧ en les écrasant grossièrement, verser le vin rouge⟦I1⟧ dessus, le verre d'alcool de fruit⟦I3⟧, la vanille⟦I4⟧, et couvrir avec un film.","Faire macérer durant 5 jours en remuant de temps en temps.","Ensuite filtrer la préparation et mettre dans une casserole avec le sucre⟦I2⟧, faire cuire en écumant et laisser bouillir 5 minutes, regardez si le sirop épaissit bien.","Laisser refroidir avant de mettre en bouteilles."],"cr-creme-de-myrtilles":["Mettre les fruits⟦I0⟧ dans une jatte en recouvrant d'un vin rouge⟦I2⟧ assez épais.","Laissez macérer 3 jours en écrasant les fruits plusieurs fois.","Exprimer le jus et ajouter 750 g de sucre⟦I1⟧ par litre de liquide ; faire bouillir 8 mn, refroidir et ajouter 1/2 du liquide en alcool⟦I3⟧.","On obtient 1,5 l de crème avec 600 gr de fruit ce qui est avantageux ; on doit attendre pour consommer bien sûr."],"cr-creme-de-feuilles-de-pecher":["Dissoudre le sucre⟦I2⟧ dans le vin⟦I0⟧, ajouter l’alcool⟦I1⟧ et les feuilles⟦I3⟧.","Mettre le tout dans un bocal hermétique, qu’il faut exposer au soleil pendant 2 mois.","Puis filtrer et mettre en bouteilles et laisser reposer quelques semaines avant de consommer."],"cr-creme-de-peches-de-vigne":["Versez 1 kg de pêches des vignes⟦I0⟧ dans un saladier en verre.","Utilisez des pêches bien mures, mais non abîmées.","Couvrez de vin blanc⟦I1⟧ de bonne qualité et pas trop sec.","Laissez reposer 2 à 3 jours, à l'abri de la poussière et des mouchettes, au frigo.","Passez le jus et pressez un peu pour en extraire tout le jus, mais pas trop.","Filtrez finement.","Faites cuire ce jus avec 250 gr de sucre⟦I2⟧ blanc par litre.","Donnez juste un bouillon et laissez refroidir.","Ajouter l’alcool⟦I3⟧ laissez reposer puis mettez dans des bouteilles bien claires.","Passer finement et bouchez soigneusement, conservez dans l'obscurité."],"cr-creme-de-poires":["Mettre dans un grand saladier les poires⟦I0⟧ épluchées en les écrasant grossièrement, verser le vin blanc⟦I1⟧ dessus, l’alcool de fruit⟦I3⟧, la vanille⟦I4⟧, et couvrir avec un film.","Faire macérer durant 5 jours en remuant de temps en temps.","Ensuite filtrer la préparation et mettre dans une casserole avec le sucre⟦I2⟧, faire cuire en écumant et laisser bouillir 5 minutes, regarder si le sirop épaissit bien.","Laisser refroidir avant de mettre en bouteille."],"cr-creme-de-pomme":["Dissoudre le sucre⟦I3⟧ dans le jus de pommes⟦I2⟧, chauffer le mélange autour de 60°C pour finir de dissoudre le sucre et laisser refroidir.","Ensuite, mélanger avec l'eau de vie⟦I1⟧ à parts égales, les pommes⟦I4⟧ pelées et écrasée grossièrement et la vanille⟦I5⟧ fendue, mettre en attente dans un endroit sombre.","Deux semaines plus tard, filtrer le jus pour en sortir les impuretés.","Ensuite le mettre en bouteille, laisser reposer de longs mois.","Six mois sont parfaits.","Se boit frappé ! !."],"cr-creme-de-prunes":["Laisser sécher les prunes⟦I0⟧ au soleil en les remuant fréquemment.","Ecraser les fruits et les noyaux au mortier et les placer dans un bocal avec la vanille⟦I2⟧.","Recouvrir d’alcool⟦I1⟧.","Boucher le bocal et laisser macérer à température douce pendant 2 mois minimum.","Filtrer et ajouter le sirop⟦I4⟧⟦I3⟧.","Laisser reposer 8 à 10 jours filtrer à nouveau et mettre en bouteilles."],"cr-creme-de-vanille":["Ouvrir les gousses de vanille⟦I0⟧ et les couper en petits tronçons.","Mettre dans une casserole les aromates⟦I2⟧⟦I3⟧, le sucre⟦I4⟧ et l’eau⟦I5⟧, puis porter le tout à ébullition.","Retirer du feu et verser l’alcool⟦I1⟧ sur la préparation.","Laisser refroidir et verser dans une jarre hermétique.","Laisser reposer 2 mois puis filtrer et mettre en bouteilles."],"cr-creme-facon-baileys":["Mélanger tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ dans le robot pour que le mélange soit lisse.","On peut garder cette préparation un mois au réfrigérateur."],"cr-creme-de-kummel":["Griller rapidement à sec les graines⟦I0⟧, puis les broyer grossièrement au pilon.","Dissoudre le sucre⟦I3⟧ dans le verre d’eau⟦I2⟧ tiède.","Laisser refroidir, puis mélanger tous les ingrédients⟦I1⟧⟦I4⟧ et laisser reposer à l’ombre deux mois en remuant régulièrement.","Filtrer soigneusement la macération et mettre en bouteilles.","La crème de kummel sera d’autant meilleure qu’il aura vieillie quelques mois."],"cr-ratafia-d-absinthe-1902":["il faut laisser macérer 15 jours dans 1 litre d'eau de vie⟦I0⟧ toutes les herbes et feuilles⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧.","Après avoir filtré on ajoute le mélange de 1/3 litre d'eau⟦I7⟧ 15 cl d'eau de fleur d'oranger⟦I5⟧ et 250 gr de sucre⟦I6⟧ que l’on aura fait dissoudre dans l’eau."],"rt-ratafia-d-angelique-1750":["Faire bouillir à feu doux 1,5 dl de crème liquide⟦I0⟧ dans une casserole.","Retirer la casserole au premier bouillon.","Chauffer sur feu doux le sucre semoule⟦I1⟧ dans une casserole, agiter légèrement cette dernière afin de bien répartir la chaleur, et laisser caraméliser, retirer la casserole, et incorporer petit à petit la crème bouillante en fouettant sans cesse.","Remettre ensuite ce caramel à cuire 2 à 3 minutes sur feu doux, puis le laisser refroidir à température ambiante.","Il est recommandé de réaliser ce caramel quelques heures à l’avance.","Fouetter énergiquement 2,5 dl de crème liquide⟦I0⟧ bien froide, y incorporer petit à petit 20 g de sucre glace⟦I2⟧.","Parfumer cette crème fouettée avec 1 cuillère à soupe de liqueur d’angélique⟦I4⟧.","Verser la crème caramel dans des coupes, mettre délicatement au dessus la chantilly et saupoudrer de cacao amer⟦I3⟧."],"rt-ratafia-de-noyaux-au-miel-1829":["Voici une recette de ratafia de noyaux qui fera connaitre combien cette sorte de liqueur est facile à faire.","Dans le temps des abricots, mettez dans un bocal quatre bouteilles d’eau de vie⟦I0⟧ ; à mesure que vous aurez des noyaux d’abricots, concassez-les sans les écraser ; mettez l’amande et le bois dans l’eau de vie.","Il faut cent noyaux par bouteille, laissez infuser ces noyaux pendant trois mois et plus.","Séparez alors l’eau de vie d’avec les noyaux en jetant le tout sur un tamis.","Mettez ensuite quatre livres de sirop de miel⟦I1⟧ dans l’eau de vie et passez au papier gris, vous aurez un ratafia limpide et excellent."],"rt-ratafia-de-brou-de-noix-1785":["Prenez quatre-vingt noix vertes, quatre pintes d’eau de vie⟦I0⟧, deux livres de sucre⟦I1⟧, girofle et muscade ou macis, un gros de chaque⟦I2⟧, une gousse de vanille et un gros de cannelle⟦I3⟧.","Vous choisissez des noix vertes et assez peu avancées pour que l’épingle passe aisément au travers ; vous les pillez et les mettez avec les aromates ; infusez dans l’eau de vie pendant 2 mois.","Au bout de ce temps, vous mettez le mélange sur un tamis de soie pour l’égoutter.","Vous faites fondre le sucre dans la liqueur, que vous laissez reposer de nouveau pendant 3 mois ; ce temps écoulé ; vous la décantez et la filtrez avant la mise en bouteilles."],"rt-ratafia-de-cassis-1820":["Pour la gelée, faire doucement éclater les baies⟦I5⟧ dans une casserole avec 1 cuillère d’eau et ajouter ensuite 3 à 4 pincées d’agar agar⟦I4⟧ et 100 gr de sucre⟦I1⟧.","Faire dissoudre, passer et laisser refroidir puis mettre au frais quelques heures.","Faire pocher les poires⟦I3⟧ pelées et évidées (garder les chapeaux) dans la décoction de fleurs⟦I0⟧.","Ajouter les 200 gr de sucre⟦I1⟧ et faire cuire à petit bouillon 20 minutes.","Egoutter les poires, les laisser refroidir, les farcir avec la gelée de cassis.","Au fond de chaque coupe, mettre deux poires remplie de gelée et remettre les chapeaux.","Mouiller le fond des coupes avec le sirop de fleur d’ibiscus.","Servir bien frais."],"rt-ratafia-de-cedrat":["Couper les cédrats⟦I1⟧ et les oranges en quartiers⟦I2⟧ ; laisser infuser dans les liquides sucrés pendant 30 jours dans un bocal bien fermé.","Presser, filtrer et mettre en bouteille.","Ancêtre du citron, le cédrat est un gros fruit ovale parfois verruqueux qui peut mesurer jusqu'à 25 cm de long et peser 4 kg.","Sa chair verte ou jaune est peu juteuse, le parfum de son zeste est très agréable.","Le zeste de cédrat est rarement utilisé frais.","Il est surtout confit et utilisé en pâtisserie, en confiserie ou à des fins décoratives.","Il est également transformé en confiture et en liqueurs.","L'essence de cédrat est employée en parfumerie.","Gelée de Cédrat Cette gelée est du pur bonheur, étalée en plus sur des tranches de brioches grillées ! ! !.","On grimpe au nirvana.","Ingrédients par pot : 4 cédrats, 4 oranges et 2 citrons, 200 gr de sucre, 1 bâton de cannelle.","Préparation :.","Presser les fruits et au jus obtenu, ajouter l’équivalent de poids en sucre, un peu de zeste de cédrat, le bâton de cannelle, une gousse de vanille.","Cuire 30 mn à très petit bouillon et mettre en bocal.","Gelée de cédrat aux pignons Ingrédients : 1 kg de cédrats, 50 g de pignons, 500 gr de sucre Préparation : Torréfier les pignons à sec dans une poêle.","Eplucher les cédrats puis Faire cuire pendant 15 mn dans 30 cl d’eau les fruits épluchés et en quartiers.","Mixer le tout puis filtrer à travers un tamis quelques heures le temps que le jus s’écoule lentement.","Puis ajouter la même quantité de sucre.","Faire prendre pendant 30 minutes environ à feu moyen, en écumant et en remuant régulièrement pour atteindre le point de gélification.","Ajouter alors les pignons, bien remuer et mettre en bocaux."],"rt-ratafia-cerises-et-framboises":["Faire fondre le sucre⟦I5⟧ à chaud dans le ½ litre d’eau⟦I6⟧, Mettre les cerises⟦I0⟧ et cuire à petit bouillon 15 mn.","Ecraser les cerises dans un chinois pour séparer la pulpe des noyaux.","Ecraser une grosse poignée de noyaux de cerises puis dans une jarre mélanger, le sirop, le jus des cerises, l’alcool⟦I2⟧ et les framboises⟦I1⟧ bien mûres et légèrement concassées.","Laisser reposer 8 semaines dans un endroit sombre en remuant régulièrement.","Passer une première fois à la passoire pour bien récupérer la macération.","Repasser finement pour bien supprimer la pulpe.","Mettre en bouteilles et laisser reposer quelques semaines avant de consommer."],"rt-ratafia-de-citronnelle-xvii-siecle":["Pour quatre pintes d’eau de vie⟦I0⟧ vous zesterez douze beaux citrons⟦I1⟧ ; ajoutez-y deux gros de cannelle concassée⟦I2⟧ et une once de grains de coriandre⟦I3⟧ ; avec deux livres de sucre⟦I4⟧ que l’on fera fondre dans une pinte et demie d’eau⟦I5⟧ ; laissez le tout infuser un mois ; passez ensuite votre liqueur et mettez-la dans des bouteilles fermées et cirées."],"rt-ratafia-de-clementines":["Peler à l’économe les clémentines⟦I2⟧ pour récupérer les zestes.","Passer les fruits au broyeur pour extraire le jus.","Broyer au mortier tous les épices⟦I3⟧⟦I5⟧⟦I6⟧.","Dans une jarre mélanger le rhum⟦I0⟧, le jus de fruit, les zestes et les épices.","Faire un sirop avec l’eau⟦I7⟧ et le sucre⟦I1⟧ et l’ajouter froid à la macération.","Laisser reposer 8 semaines à l’ombre, avant de filtrer finement, et de mettre en bouteilles.","Oh my darling Clementine !!.","On pense que \"Clémentine\" a été écrite par Percy Montrose vers 1883 Clementine In a cavern, in a canyon Excavating for a mine Lived a miner forty-niner And his daughter, Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","Light she was and like a fairy And her shoes were number nine Herring boxes without topses Sandals were for Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","Drove she ducklings to the water Every morning just at nine Hit her foot against a splinter Fell into the foaming brine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","Ruby lips above the water Blowing bubbles soft and fine But, alas, I was no swimmer, So I lost my Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","In a churchyard near the canyon Where the myrtle doth entwine There grow roses and the posies Fertilized by Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","Then the miner, forty-niner Soon began to peak and pine Thought he oughter join his daughter Now he's with his Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","In my dreams she still doth haunt me Robed in garments soaked in brine Though in life I used to hug her Now she's dead, I'll draw the line.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine.","How I missed her, how I missed her How I missed my Clementine Till I kissed her little sister And forgot my Clementine.","Oh, my darling, oh, my darling Oh, my darling Clementine You are lost and gone forever Dreadful sorry, Clementine Clementine Dans une caverne, dans un canyon Creusant une galerie Vivait un mineur de quarante-neuf ans Et sa fille Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Elle était légère et comme une fée Et elle chaussait du quarante-trois Des boîtes de harengs sans couvercle Étaient les sandales de Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Elle conduisait les canetons à l'eau Tous les matins à neuf heures Elle se cogna le pied contre un bout de bois Et tomba dans la saumure écumante Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Ses lèvres de rubis au-dessus de l'eau Faisaient de jolies bulles délicates, Mais hélas, je ne savais pas nager Aussi je perdis ma Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Dans le cimetière, près du canyon, Où le myrte s'entrelace Là poussent des roses et des bouquets Fertilisés par Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Puis le mineur de quarante-neuf ans Commença bientôt à avoir des hauts et des bas Il pensa qu'il devrait rejoindre sa fille Maintenant il est avec Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Dans mes rêves, elle me hante encore Vêtue d'habits trempés d'eau salée Quand elle vivait, je la serrais dans mes bras Maintenant qu'elle est morte, c'est terminé.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine.","Comme elle me manqua, comme elle me manqua Comme ma Clémentine me manqua, Jusqu'à ce que j'embrasse sa petite sœur Et que j'oublie ma Clémentine.","Oh, ma chérie, oh ma chérie, Oh, ma Clémentine chérie.","Tu es perdue et partie à jamais.","Je suis terriblement désolée, Clémentine."],"rt-ratafia-de-coings":["Eplucher les coings⟦I0⟧ et les couper en fines tranches Les mettre dans un récipient, les couvrir de vin⟦I1⟧ et les laisser mariner au moins 3 heures.","Ranger les coings et bien les étaler dans une marmite.","Ajouter les épices⟦I3⟧⟦I4⟧⟦I5⟧, le sucre⟦I2⟧ et le zeste d'agrume.","Cuire pendant 1h à 1h30 à petit bouillon le temps que les coings deviennent bien tendres et le vin un peu sirupeux.","Laisser reposer quelques heures au frais dans le sirop de cuisson."],"rt-ratafia-de-fleurs-au-miel":["Macérez seulement pendant 3 jours dans un litre de bonne eau-de-vie⟦I7⟧ : 250 grammes de pétales de rose odorante ou de fleurs de violettes⟦I2⟧ et d'autres fleurs parfumées ; filtrez puis ajoutez 180 à 200 grammes de miel liquide⟦I5⟧ par litre de préparation."],"rt-ratafia-de-fleurs-d-orangers":["Prenez huit pintes d’eau de vie⟦I0⟧, quatre livres de sucre⟦I1⟧ et une livre et demie de fleur d‘orange⟦I2⟧, la plus blanche possible.","Vous faites fondre el sucre dans la quantité d‘eau⟦I3⟧ nécessaire, et vous y mettez votre fleur d’orange épluchée ; lorsqu’elle à reçu un bouillon vous retirez le mélange du feu, vous le laissez refroidir, puis le mettez dans un vase de grés et y versez l’eau de vie, tenez hermétiquement fermé, et laissez infuser pendant dix-huit ou vingt jour ; après cela, vous filtrez le ratafia.","On nous a rapporté qu’il a été fait de ce ratafia, à partir d’eau de fleur d’oranger.","Dans ce cas il faut mettre 2 pintes d’eau de fleur d’oranger à la place des fleurs."],"rt-ratafia-de-framboises":["Prenez huit pintes d’eau de vie⟦I0⟧, quatre de jus de framboise, une de jus de cerise et quatre livres de sucre⟦I1⟧.","Lorsque vous aurez fait fondre le sucre dans le jus des fruits, vous y ajoutez l’eau de vie, et laissez reposer le mélange un bon mois.","Aussitôt que la liqueur est claire vous la décantez, la filtrez et la mettez en bouteilles Racontar n'a pas de fruit, fleur n'a pas de paille."],"rt-ratafia-de-genievre":["Prenez quatre pintes d’eau de vie⟦I0⟧, deux livres de sucre⟦I1⟧, une livre d’eau de rivière⟦I2⟧, douze onces de baies de genièvre⟦I3⟧, d’anis, de cannelle, de coriandre, et de girofle, un gros de chaque⟦I4⟧.","Concassez les graines et les aromates, et mettez les infuser dans l’eau de vie pendant 3 semaines.","Après ce temps, vous passez le mélange à travers un tamis ; vous y ajoutez le sucre que vous avez fait fondre dans l’eau de rivière, ensuite vous décantez puis vous filtrez le ratafia.","Liège pont des arches buveur de Gin Je ne bois jamais rien de plus fort que le gin avant le petit déjeuner.","W.C.","Fields."],"rt-ratafia-de-grenade":["Egrainer les grenade⟦I0⟧ et les mettre à macérer 1 jour au frais avec le sucre⟦I2⟧ et le verre d’eau⟦I5⟧.","Bien remuer et verser le tout dans une jarre et recouvrir d’alcool⟦I1⟧.","Ajouter alors la vanille fendue⟦I4⟧ et la cannelle broyée⟦I3⟧.","Oublier pendant 4 semaines dans un endroit sombre.","Filtrer au travers un drap pour bien récupérer tout le jus des grenades et mettre en bouteilles.","Cet alcool très parfumé vieillit très bien.","Méditation Tous les champignons sont comestibles.","Certains ne le sont qu'une fois !.","Importance pour la médecine Plus de 250 études scientifiques montrent que la grenade pourrait avoir un effet positif en cas de maladies cardiovasculaires, cancers et arthrite.","Dans une étude in vitro, on a pu constater un effet protecteur du jus de grenade contre les cellules du cancer du sein ainsi que sur les cellules de la leucémie.","Dans une étude sur une culture cellulaire datant de 2008 on a pu montrer en outre que le jus de grenade peut avoir un effet positif même à un stade avancé du cancer de la prostate.","Salvador Dali Le tableau reprend la théorie de Sigmund Freud selon laquelle le rêve transforme les éléments extérieurs qui perturbent le lecteur en objets oniriques, et les amplifie.","En effet, ce rêve traduit la crainte de Gala, d'une piqure d'abeille.","Il est généré par le bourdonnement de l'insecte autour de la pomme-grenade (en bas, à droite).","De celle-ci jaillit un poisson, dont sort un tigre ; du tigre sort un deuxième tigre qui pointe un fusil à baillonette sur le bras de Gala.","L'accumulation de ces éléments, de plus en plus agressifs, montrent qu'une menace pèse sur la femme.","De plus, le pic de la baillonette peut renvoyer au dard de l'abeille, tout comme la couleur du pelage des tigres.","La menace de la piqure, qui dans la réalité semble minime, est ici amplifiée.","Titre de l'oeuvre Rêve causé par le vol d'une abeille autour d'une grenade, une seconde avant l'éveil.","Salvatore Dali."],"rt-ratafia-de-grenoble-ou-de-teissier":["Prenez quinze pintes (952 ml) de jus de merises, douze de bonne eau-de-vie, six livre de sucre⟦I0⟧, deux livres de feuilles de cerises⟦I1⟧, trois gros de cannelle fine⟦I2⟧ et un gros de girofle, ou de chaque en plus grande quantité, pourvu que vous observiez les proportions.","Vous avez à part une suffisante quantité de merises, dont vous supprimez les queues ; vous séparez les noyaux que vous concassez et exprimez le jus à la presse.","Vous le mêlez avec votre sucre que vous avez fait fondre, et versez le tout dans un tonneau ; vous y ajoutez l’eau de vie⟦I5⟧, la cannelle, le girofle et les feuilles de cerises, et vous laissez déposer le mélange.","Lorsqu’il est clair, vous les soutirez et le collez ; au bout de 10 à 12 jours vous pouvez le mettre en bouteilles.","Si vous voulez donner plus de goût à votre liqueur, vous y ajoutez aux doses ci-dessus une livre d’amandes de cerises⟦I3⟧, d’abricots ou de pêches.","Mais plus simplement aujourd'hui 2 litres de jus de cerise⟦I4⟧, 1,5 litre d’alcool à 40°, 50 feuilles de cerisier, 600 gr de sucre, 15 gr de cannelle broyée⟦I6⟧, un clou de girofle.","Broyer 1 kg de cerise sans la queue⟦I7⟧, puis concasser les noyaux.","Ajouter le jus et les noyaux cassés et les amandes à la préparation.","Laisser reposer dans une jarre 5 à 6 semaines en remuant de temps en temps.","Passer finement, laisser décanter et refiltrer.","Mettre en bouteille."],"rt-ratafia-de-groseilles":["Prenez quatre pintes d’eau de vie⟦I0⟧, deux de jus de groseilles, deux livres de sucre concassé⟦I1⟧, un gros de cannelle⟦I2⟧ aussi concassé, et un gros de girofle⟦I3⟧.","Vous avez égrené vos groseilles avant de la mettre à la presse pour en exprimer le jus, vous avez rectifié l’eau de vie en y ajoutant les aromates ; vous réunissez les liqueurs et les laissez reposer pendant un mois.","Après ce temps, vous décantez le mélange, y faites fondre le sucre et filtrez le ratafia.","Rions Au paradis on est assis à la droite de Dieu.","C'est normal, c'est la place du mort.","Groseillier et médecine, ce que l'on en pensait au XIX siècle Les feuilles de groseillier mélangées à la même quantité de réglisse (30 grammes) de chaque pour un litre d'eau en décoction⟦I4⟧), donnent une boisson très rafraîchissante et qui pousse aux urines.","Nous la conseillons volontiers dans l’hydropisie (insuffisance cardiaque), la gravelle, les rétentions d'urine, la goutte, le rhumatisme et les inflammations de l'estomac et des intestins."],"rt-ratafia-de-guignolet-a-l-ancienne":["Dénoyauter les cerises noires⟦I0⟧ et les guignes⟦I1⟧.","Y mélanger les griottes⟦I2⟧ et les framboises⟦I3⟧ et écraser le tout.","Verser dans un récipient ouvert en ajoutant l’alcool⟦I4⟧, le sirop⟦I6⟧⟦I5⟧ la cannelle⟦I7⟧ et le macis⟦I8⟧.","Laisser à l’air libre une semaine.","Fermer alors le récipient et laisser macérer 2 mois.","Filtrer la préparation et la laisser décanter quelques jours.","Filtrer de nouveau et mettre en bouteilles.","Laisser vieillir 6 mois avant de consommer."],"rt-ratafia-de-jonquilles":["Eplucher les fleurs⟦I1⟧, rejeter étamines et calices, les mettre à macérer dans l’eau-de-vie⟦I0⟧ pendant 24 heures.","Faire un sirop en chauffant sucre⟦I2⟧ et eau⟦I3⟧, le verser tiède dans l’eau-de-vie de macération.","Boucher et attendre 30 jours.","Filtrer, mettre en bouteilles, laisser reposer 1 mois avant de servir."],"rt-ratafia-de-mures":["Prenez huit pintes d’eau de vie⟦I0⟧, une d’eau de rivière⟦I1⟧, trois livres et demie de sucre⟦I2⟧, trois livres de mûres⟦I3⟧, demie-livre de groseilles rouges⟦I4⟧, autant de framboises⟦I5⟧ et demi gros de macis⟦I6⟧.","Après avoir égrené les groseilles, réunissez tous les fruits, écrasez-les tous ensemble, et mettez-en le jus, ainsi que le macis, infusez dans le macis pendant quinze à dix-huit jours.","Alors vous faites fondre le sucre dans la pinte d’eau, vous y décantez la liqueur, y mêlez l’eau de vie, la filtrez et la mettez en bouteilles."],"rt-ratafia-de-noyaux":["Prenez quatre pintes d’eau de vie⟦I0⟧, deux livres de sucre concassé⟦I1⟧, une livre d’eau de rivière⟦I2⟧, une livre et un quart d’amandes d’abricots⟦I3⟧ ou de pêches ; un gros de cannelle⟦I4⟧ et ou de girofle.","Vous avez soin que vos amandes soient fraîches ; vous leur enlevez la peau, les concassez et les mettez dans un vase de grès, avec la cannelle infusez trois ou quatre mois ; alors vous passez le mélange au tamis, auquel vous ajoutez le sucre que vous avez fais fondre dans votre eau de rivière, ensuite vous filtrez la liqueur."],"rt-ratafiat-de-noix-recette-du-vxii-siecle":["Le ratafia de noix se fait vers le temps de la Magdeleine (fin juillet) que les noix sont formées ; pour deux pintes d’eau de vie⟦I0⟧ que vous mettrez dans une cruche bien bouchée.","Vous y mettrez quinze à seize noix entières⟦I1⟧ que vous fendrez par la moitié ; mettez votre cruche à la cave pour y laisserez infuser les noix avec l’eau de vie environ 4 à 5 semaines.","Vous aurez soin de bien remuer la cruche au moins 2 fois par semaine pour bien mêler les noix et l’eau de vie et lui en communique parfaitement le goût.","Ensuite vous filtrerez l’eau de vie et le remettrez dans la cruche avec une livre et demie de sucre⟦I2⟧ deux clous de girofle⟦I3⟧, un petit bâton de cannelle⟦I4⟧ et très peu de macis⟦I5⟧ (noix de muscade).","Faites encore infuser le tout l’espace de trois semaines, ensuite vous filtrerez et mettrez en bouteille.","Plus vous garderez ce ratafia meilleur il deviendra."],"rt-ratafia-de-peches":["Laisser bien mûrir les poires⟦I0⟧ puis les peler.","Concasser la pulpe des fruits et broyer au mortier les épices⟦I4⟧⟦I5⟧⟦I7⟧.","Dans une jarre mélanger, la peau et la purée de fruits, les épices, la vanille fendue⟦I6⟧.","Le sirop refroidi de sucre⟦I3⟧ et d’eau⟦I2⟧.","Laisser reposer dans un endroit sombre pendant 8 semaines en remuant de temps en temps.","Filtrer finement pour supprimer la pulpe et mettre en bouteilles."],"rt-ratafia-de-raisin-muscat":["Vous prendrez du raisin muscat bien mûr, vous l’égrènerez ; écrasez-le et pressez –le pour en tirer le jus⟦I0⟧ ; pour trois pintes de jus, vous mettrez trois pinte d’eau de vie⟦I1⟧ dans une cruche bien bouchée ; vous ajouterez deux gros de cannelle⟦I2⟧ et deux livres de sucre, que vous ferez fondre dans le jus de raisin ; laissez infuser le tout pendant quinze jours ; ensuite passez-le à la chausse, et le mettrez en bouteilles.","L’on peut également faire cette liqueur avec du muscat noir ; prenez-le toujours bien mûr, ayez soin de le bien éplucher, et qu’il ne s’y trouve point de grains gâtés."],"rt-ratafia-de-rossoli-dit-populo":["Ecraser grossièrement les différentes épices⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧ dans un mortier, les mettre dans un bocal avec 1 litre d’eau-de –vie⟦I0⟧, remuer, boucher et laisser 30 jours.","Faire un sirop clarifié en chauffant le sucre⟦I5⟧ et l’eau⟦I6⟧, laisser refroidir et y verser 1’alcool filtré.","Mélanger et mettre en bouteilles.","Avant de servir attendre quelques semaines.","La Citation Mal aux dents a carnivore.","N'en devient par herbivore.","Charles de Leuss Drosea Rodontifolia : la petite histoire Elle affectionne les tourbières acides à sphaignes localement abondante.","Ils colonisent souvent en grand nombre les « coussins » de sphaigne vivante ou morte lorsque l'exposition au soleil est abondante.","Mais elle reste assez rare en France, se rencontre généralement entre 600 à 2000 m d'altitude, mais on peut en trouver à des altitudes inférieures à 400 m, comme dans la tourbière Saint-Jean située sur le territoire de la commune de Bertrichamps (Meuthe et Moselle).","Elle se trouve également dans les régions tempérées de l'hémisphère nord (Amérique du Nord, Europe, Asie).","Catherine de Médicis (1515-1589) est une figure emblématique du xvie siècle.","Son nom est irrémédiablement attaché aux guerres de Religion opposant catholiques et protestants.","Partisane d'une politique de conciliation, elle est l'instauratrice en France de la liberté de conscience pour les protestants, et a de nombreuses fois tenté de faire accepter le concept de tolérance civile.","Une légende noire persistante la dépeint comme une personne acariâtre, jalouse du pouvoir, ne reculant devant aucun crime pour conserver son influence.","Aujourd'hui, la tendance historiographique la réhabilite, et reconnaît en elle une des plus grandes reines de France.","Néanmoins, son rôle dans le massacre de la Saint-Barthélemy contribue à en faire une figure controversée."],"rt-ratafia-de-semences-chaudes-ou-eau-des-sept-graines-1730":["Piler 60 g de chaque graine ou semence chaude, majeure et mineure⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧.","Les mettre à infuser six semaines dans huit litres d'eau-de-vie⟦I8⟧.","Ajouter par litre 180 g de sucre⟦I9⟧ cassé en gros morceaux, trempés dans l'eau avant d'être jetés dans l'eau-de-vie.","L'infusion achevée, passer le ratafia à la chausse quelques jours plus tard.","Plus il est gardé, meilleur il devient."],"rt-ratafia-de-vanille":["Faire macérer dans 2 litres d’alcool à 40°⟦I0⟧, 4 gousses de vanille⟦I1⟧ que vous aurez fendues.","Il faut bien racler les graines et le mettre également dans l’alcool.","Laissez infuser la vanille coupée par le milieu et en long pendant 15 jours.","Dissoudre le sucre⟦I2⟧ dans un peu d’eau⟦I3⟧ et ajoutez ce sirop à la préparation.","Laisser poser 1 semaine, filtrer et mettre en bouteille Les plantes qui produisent la vanille portent elles-mêmes le nom de vanille, ou parfois de vanillier.","Ce sont les seules orchidées cultivées pour des raisons autres qu'ornementales.","La culture et la préparation de la vanille nécessitent, pour obtenir une épice richement aromatique, des soins longs et attentifs.","Cela en fait, rapporté au poids, l'un des produits agricoles les plus chers au monde.","Il se présente sous la forme de bâtonnets noirs et luisants, communément appelés « gousses de vanille ».","Botaniquement, il s'agit cependant de capsules.","Au Mexique pays d'origine de la vanille c'est une abeille se charge de la pollinisation naturelle de la fleur d'Orchidée.","Pour toutes les autres contrées ou la plante à été introduite par les Européens , il faut faire une pollinisation manuelle.","La petite Fleur de Vanille."],"rt-ratafia-des-quatre-fruits-xviiie-siecle":["Otez les queues de cerises⟦I0⟧, exprimez le jus de vos fruits réunis, et y mettez par pinte de jus cinq ou six onces de sucre fondu ; vous y ajoutez autant de pintes d’eau de vies que vous avez de jus de fruit, deux gros de girofle et un gros de macis ; lorsque la liqueur est bien reposée et éclaircie, vous la décantez et la mettez en bouteilles.","A l'époque il fallait très certainement des tonneaux ou des comportes pour réaliser de tel assemblage !!.","Pensée Pour connaître l'origine et la qualité d'un vin, il n'est pas nécessaire de boire le tonneau entier.","Oscar Wilde Du rhum des femmes - Soldat Louis."],"rt-ratafia-d-illets-1":["Enlever l’onglet aux pétales d’œillets⟦I1⟧ ; verser dessus l’eau tiède⟦I4⟧ et laisser infuser pendant 2 jours, presser et passer ce mélange ; ajouter le sucre⟦I5⟧, l’eau de vie⟦I3⟧, la cannelle⟦I2⟧ et la coriandre.","Mélanger bien le tout et laisser infuser pendant 4 semaines.","Filtrer et mettre en bouteilles."],"rt-ratafia-d-illets-2":["Prenez six pintes d’eau de vie⟦I0⟧, une pinte d’eau de rivière⟦I1⟧, trois livres de sucre⟦I2⟧, deux livres de pétales d’œillets rouges⟦I3⟧, et un gros de girofle⟦I4⟧.","Après avoir séparé les onglets de vos pétales, c'est-à-dire, la partie inférieure, et qui n’est pas de la même couleur, vous ne prenez que la partie rouge, que vous faites infuser dans l’eau de vie pendant deux mois.","Vous y avez mis votre girofle en même temps ; après cela, vous passez le mélange à travers un linge blanc que vous pressez ; vous versez dedans le sucre que vous avez fais fondre dans votre eau de rivière ; ensuite vous pressez la liqueur et la mettez en bouteilles."],"rt-ratafia-d-oranges-du-portugal":["Vous zesterez douze belles oranges non traitées, que vous choisissez les plus épaisses de peau ; vous les mettez à mesure dans quatre pintes d’eau de vie⟦I0⟧, que vous aurez mise dans une cruche ; vous ferez fondre deux livres de sucre⟦I1⟧ dans le jus des oranges que vous aurez pressées ; mêlez le tout ; bouchez bien la cruche, et laissez là pendant deux mois en infusion ; après ce temps ; passez-la et mettez-la dans des bouteilles."],"rt-hypocras-a-la-vanille":["Triturez 7 décigrammes de bonne vanille des îles avec 125 grammes de sucre⟦I0⟧, versez-y 2 litres de bon vin rouge⟦I1⟧ et 125 grammes d’alcool à 85°, après dix jours de macération filtrez."],"rt-hypocras-a-la-violette":["Faites digérer pendant une semaine ou deux, 6 grammes d’iris de Florence⟦I0⟧ et 7 décigrammes de girofle en poudre, avec un litre de vin rouge ou blanc⟦I1⟧, ajoutez le sucre et l’esprit, une goutte d’ambre et de musc.","Mais il est possible de remplacer le musc par des graines d’ambrette broyées.","Filtrez soigneusement la préparation."],"hy-hypocras-a-l-angelique":["Faites infuser à froid, pendant dix jours, dans un litre de vin rouge ou blanc⟦I0⟧, 8 grammes d’angélique fraîche⟦I1⟧ avec une pincée de muscade en poudre, ou 16 grammes de la même plante confite⟦I2⟧ ; ajoutez le sucre et 60 grammes d’esprit⟦I3⟧, et filtrez."],"hy-hypocras-a-l-orange":["Versez sur les zestes de deux grosses oranges et 20 feuilles ; un litre de bon vin⟦I0⟧ et 60 grammes d’alcool, après une semaine d’infusion, ajoutez 90 grammes de sucre en poudre⟦I1⟧, agitez de temps en temps et filtrez le lendemain.","Ou bien, frottez 60 grammes de sucre en gros morceaux sur l’écorce d’une orange⟦I2⟧, jusqu’à ce que le sucre soit bien imprégné de l’huile essentielle du fruit ; faites le fondre dans le vin et filtrez."],"hy-hypocras-au-cedrat":["Versez sur les zestes d’un gros cédrat un litre de bon vin⟦I0⟧ et 60 grammes d’alcool, après une semaine d’infusion, ajoutez 90 grammes de sucre en poudre⟦I1⟧, agitez de temps en temps et filtrez le lendemain.","Ou bien, frottez 60 grammes de sucre en gros morceaux sur l’écorce d’un cédrat⟦I2⟧, jusqu’à ce que le sucre soit bien imprégné de l’huile essentielle du fruit ; faites le fondre dans le vin et filtrez."],"hy-hypocras-aux-cerises":["écraser les cerises⟦I3⟧ pour faire éclater la pulpe.","Mélanger au vin rouge⟦I0⟧, ajouter le sucre⟦I2⟧ et l’alcool⟦I1⟧.","Verser dans une bonbonne et laisser exposer au soleil 2 semaines.","Filtrer finement la préparation, laisser décanter et mettre en bouteilles.","Servir bien frais."],"hy-hypocras-au-genievre":["Faites macérer à froid pendant 48 heures, 30 grammes de baies de genièvre concassées⟦I0⟧, bien mûres et bien fraîches, avec un litre de vin⟦I1⟧ et 30 à 60 grammes d’esprit, ajoutez tant soit peu de vanille ou d’ambre, 60 à 90 grammes de sucre en poudre⟦I2⟧, et filtrez."],"hy-hypocras-au-vin-d-absinthe":["Faites infuser pendant 48 heures, dans un litre de vin blanc⟦I0⟧, une poignée d’absinthe fraîche⟦I1⟧, 60 ou 90 grammes de sucre en morceaux⟦I2⟧, frotté sur l’écorce d’un citron ou d’un petit cédrat, 4 grammes d’anis concassé⟦I3⟧, cinq à six clous de girofle en poudre ; ajoutez 60 grammes d’alcool⟦I4⟧, passez avec expression et filtrez."],"hy-hypocras-aux-epices-1":["Mettez dans une grande bouteille 4 grammes de cannelle de chine⟦I0⟧, deux ou trois clous de girofle, 15 grammes de muscade⟦I1⟧, une pincée de macis, le tout en poudre, et ajoutez 30 à 60 grammes d’alcool à 40°⟦I2⟧; après 10 jours de digestion, ajoutez un litre de vin blanc ou rouge 13°⟦I3⟧, deux ou trois gouttes d’essence d’ambre, et 60 à 90 grammes de sucre en poudre⟦I4⟧, agitez et filtrez le lendemain."],"hy-hypocras-aux-epices-2":["Râper le gingembre⟦I1⟧ et concasser les épices⟦I2⟧⟦I3⟧⟦I4⟧.","Mélanger au vin⟦I0⟧ avec le sucre (ou le miel)⟦I5⟧, l'eau de rose⟦I6⟧ et l'alcool⟦I7⟧.","Laisser infuser à froid quelques jours en remuant.","Filtrer soigneusement et mettre en bouteilles."],"hy-hypocras-aux-epices-3":["On fait infuser pendant 10 à 12 jours, dans du vin de chablis⟦I6⟧, 30 grammes de cannelle de ceylan en poudre⟦I0⟧, 15 grammes de macis⟦I1⟧, 15 grammes de muscade⟦I2⟧, 60 grammes d’amandes amères⟦I3⟧, 100 grammes de vanille pilée⟦I4⟧ avec du sucre.","On tire au clair, on ajoute 20 kilo de sucre fondu⟦I8⟧ dans un peu d’eau et 10 litres d’alcool à 85°⟦I5⟧.","Après quelques jours de repos, on colle, on filtre et on met en bouteilles.","Dans des proportions plus raisonables pour nous.","Faire infuser dans 2 litres de vin de chablis, 3 gr de cannelle en poudre⟦I7⟧, 2 gr de macis, 2 gr de muscade, 5 gr d’amandes amères, 1 gousse de vanille, 1 kg de sucre fondu dans 0,5 L d’eau et 2 litres d’alcool à 40°.","Laisser au repos pendant 30 jours, puis filtrer et laisser décanter.","Mettre alors en bouteille et de consommer qu’après quelques semaines."],"hy-hypocras-au-miel":["Faire dissoudre le miel⟦I0⟧ avec le ½ litre d’eau, ouvrir la gousse de vanille⟦I1⟧ et la tronçonner en tronçons.","Broyer les autres épices⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧⟦I8⟧, puis tout mettre à macérer dans le vin⟦I3⟧ pendant 12 heures.","Ajouter alors le miel dilué et l’alcool⟦I2⟧.","Mettre le tout dans une bonbonne hermétique et laisser reposer 20 jours.","Filtrer finement la préparation et mettre en bouteilles.","Consommer après quelques mois de cave."],"hy-hypocras-aux-noyaux":["Cassez douze noyaux d’abricots et six noyaux de pêches, sans endommager les amandes, faites infuser celles-ci avec leur bois, pendant 10 jours, dans un litre de vin blanc⟦I0⟧ ; ajoutez 4 décigrammes de vanille triturée avec 60 grammes de sucre⟦I1⟧, un peu d’esprit, et filtrez."],"hy-hypocras-de-la-marquise":["Prélever finement les zestes des agrumes⟦I2⟧⟦I3⟧ puis presser les fruits.","Couper les abricots⟦I8⟧ et faire éclater les noyaux.","Débiter les pommes⟦I9⟧ en lamelle fines.","Ajouter tous les autres ingrédients⟦I0⟧⟦I1⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧⟦I10⟧⟦I11⟧.","Faire macérer dans une jarre au frais pendant 5 journées en agitant régulièrement.","Filtrer la préparation puis mettre en bouteilles, Se sert bien frais."],"hy-hypocras-framboise":["Remplissez un entonnoir à grille, de framboises fraichement cueillies et point écrasées ; faites filtrer à travers un litre de vin rouge⟦I0⟧ ; ajoutez 60 grammes d’esprit⟦I1⟧, le sucre nécessaire et filtrez.","La grande quantité du principe mucilagineux contenu dans la framboise, ferait promptement tourner le vin, si on la laissait en digestion avec le fruit.","On peut préparer de la même manière un fort joli vin de fraise."],"hy-hypocras-rouge-ou-blanc":["Pour 3 litres de boisson⟦I0⟧ : 3 litres de vin rouge ou blanc⟦I1⟧ ; 180g de sucre roux (que l'on peut remplacer par du miel) ; 3 cuillères à soupe de miel (que l'on peut remplacer par du sirop de fraise) ; 30 gr de cannelle râpée⟦I2⟧ ; 2 cuillères à soupe de gingembre frais râpé ; 1 cuillère à café de noix de muscade râpée ; 1 cuillère à café de macis (l'arille, ou bogue, de la noix de muscade), de clou de girofle et de cardamome, le tout pilé ; 1 pincée de poivre noir ; Piler les différentes épices au mortier.","Mettre le tout dans un cul-de-poule ; Mouiller avec un peu de vin pour lier les épices.","Ajouter le sucre ou le miel liquéfié au bain-marie.","Faire chauffer le vin à feu très doux sans ébullition.","Ajouter au vin chaud la soupe d'épices.","Mettre en bocaux et laisser reposer une semaine.","Au bout d'une semaine, filtrer l'ensemble avec un linge puis mettre en bouteilles.","Laisser la boisson reposer un mois avant dégustation.","Les bouteilles peuvent se conserver plusieurs années, mais une fois ouverte son contenu doit être consommé dans la semaine."],"hy-vin-d-amour-en-cage":["faire dissoudre le miel⟦I1⟧ dans le vin⟦I2⟧, ajouter les fruits⟦I0⟧ écrasés et l’alcool⟦I3⟧.","Bien boucher et laisser macérer 15 jours dans une jarre.","Filtrer finement et mettre en bouteilles."],"hy-vin-d-artichaut":["couper finement les feuilles⟦I2⟧ puis mélanger le sucre⟦I0⟧, le vin⟦I1⟧ et l’alcool⟦I3⟧.","Laisser reposer 2 semaines puis filtrer et mettre en bouteilles."],"vn-jus-d-andouille-blanc":["Couper en morceaux les agrumes⟦I3⟧⟦I4⟧, peler les bananes⟦I5⟧.","Laisser macérer tous les ingrédients dans une grosse bonbonne pendant 3 semaines.","Filtrer et mettre en bouteilles."],"vn-vermouth-blanc-a-la-camomille":["Faire macérer une semaine au soleil dans le vin blanc⟦I0⟧, les fleurs de camomille⟦I2⟧ et les zestes des deux oranges amères⟦I3⟧.","Ajouter le sucre⟦I4⟧ et l’alcool⟦I1⟧.","Prolonger la macération 30 jours en remuant régulièrement pour faire fondre le sucre.","Filtrer et mettre en bouteilles.","Ce vermouth amer maison, est à boire très frais, mais après quelques mois de cave."],"vn-vin-chaud-aux-epices":["Verser le vin⟦I0⟧ et l'alcool⟦I10⟧ dans une casserole et faire bouillir, ajouter le sucre⟦I5⟧, les épices⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I8⟧⟦I9⟧ et les zestes⟦I6⟧⟦I7⟧.","Laisser chauffer à feu doux 20 mn, filtrer le vin et servir bien chaud."],"vn-vin-chaud-traditionnel":["Détailler l'orange⟦I0⟧ et le citron⟦I1⟧ en rondelles.","Les mettre dans une casserole.","Ajouter tous les autres ingrédients et faire chauffer.","Juste avant l'ébullition, retirer du feu, couvrir et laisser infuser quelques minutes.","Servir chaud."],"vn-vin-d-ecorce-de-bouleau":["Sécher l’écorce et la réduire en petits bouts, Faire macérer dans une jarre l’écorce⟦I0⟧, le miel⟦I2⟧, le vin⟦I1⟧ et l'alcool⟦I3⟧ pendant 15 jours.","Filtrer finement et mettre en bouteille."],"vn-vin-a-la-reine-des-pres":["Mélanger tous les ingrédients dans le vin⟦I2⟧, dissoudre le miel⟦I5⟧ et ajouter la gousse de vanille⟦I6⟧ fendue.","Laisser macérer 15 jours et mettre en bouteilles pour faire vieillir quelques mois.","Cette préparation à des propriétés sédative et calmante, prendre un petit verre le soir au coucher."],"vn-vin-a-l-angelique":["Faire macérer dans une jarre l’angélique⟦I0⟧, lavée rapidement puis débitée en petits tronçons.","Faire dissoudre le sucre⟦I2⟧ dans le vin⟦I1⟧ et ajouter l’alcool⟦I3⟧.","Laisser reposer 2 semaines, filtrer et mettre en bouteilles.","Un petit verre de ce vin est un excellent remède en cas de digestion difficile ou d’état fébrile."],"vn-vin-a-l-ananas":["Peler et couper l’ananas⟦I2⟧ en morceaux.","Mettre tous les ingrédients dans une jarre et laisser macérer environ 35 jours, brasser régulièrement.","Filtrer et mettre en bouteilles."],"vn-vin-de-basilic":["Hacher finement le basilic puis mélanger dans une jarre, le vin⟦I1⟧, le sucre⟦I2⟧, l’alcool⟦I3⟧ et le basilic⟦I0⟧.","Faire macérer 15 jours puis filtrer finement et mettre en bouteilles."],"vn-vin-de-bleuet":["Faire macérer les fleurs⟦I0⟧ dans une jarre avec le vin⟦I1⟧, le miel⟦I2⟧ et l’alcool⟦I3⟧ pendant un mois.","Remuer de temps en temps puis filtrer finement et mettre en bouteilles."],"vn-vin-au-cresson":["Hacher grossièrement la botte de cresson⟦I0⟧, puis mettre à macérer tous les éléments dans une jarre.","Laisser reposer 15 jours, puis filtrer et mettre en bouteilles."],"vn-vin-a-l-orange-amere":["Brosser les oranges non traitées sous l'eau chaude pour bien les nettoyer, Dans un grand bocal, vider les 2 bouteilles de vin⟦I0⟧.","Ajouter l'alcool de fruits⟦I1⟧, le sucre⟦I2⟧, le jus de citron⟦I5⟧, la gousse de vanille⟦I6⟧ fendue et la cannelle⟦I7⟧.","Ajouter les oranges⟦I3⟧⟦I4⟧ coupées en quartier avec la peau.","Compléter au besoin avec le reste du vin pour que la bouteille soit bien pleine Fermer le bocal, puis agiter.","Conserver dans un endroit sombre et laisser macérer pendant 40 jours.","Penser à remuer le bocal environ 1 fois par semaine.","Filtrer le contenu du bocal à travers une passoire fine en pressant un peu les oranges ; mettre en bouteille.","Laisser au repos quelques semaines avant de consommer bien frais."],"vn-vin-de-quinquina-blanc":["On doit d’abord faire macérer l’écorce de quinquina⟦I3⟧ dans l’eau⟦I1⟧ pendant 5 jours au frais.","Puis dans une jarre on verse le vin⟦I0⟧, l’alcool⟦I8⟧, et tous les autres composants broyés.","Mettre dans un endroit sombre puis remuer régulièrement pendants 10 jours.","Filtrer finement et mettre en bouteille."],"vn-vin-rose-au-quinquina":["Faire dabord dissoudre le sucre⟦I8⟧ dans le vin⟦I0⟧ et le verser dans un bocal.","Y mettre infuser tous les ingrédients.","Après 30 jours de macération, filtrer et ajouter alors l'eau-de-vie⟦I6⟧.","Mettre en bouteille et laisser reposer quelques semaines avant de consommer frais."],"vn-vin-blanc-de-fraises":["Lavez et équeutez les fraises⟦I1⟧, coupez-les en morceaux et mixez-les avec le sucre⟦I3⟧ et un peu de vin blanc⟦I0⟧.","Versez le coulis dans un récipient pouvant être refermé, ajoutez le reste de vin blanc, mélangez bien et laissez macérer au frigo 48 heures.","Prendre un grand récipient, posez une passoire dessus et le morceau de gaze⟦I4⟧ dans la passoire, ensuite versez le vin petit à petit en pressant bien la pulpe avec le dos d'une cuillère et ajouter l'alcool⟦I2⟧.","Le vin de fraise se boit bien frais."],"vn-vin-aux-fraises-et-au-vin-rouge":["Ecraser les fraises⟦I0⟧, mélanger tous les autres ingrédients⟦I2⟧⟦I3⟧⟦I4⟧ et la gousse de vanille⟦I1⟧ fendue.","Laisser macérer 3 mois, puis filtrer et mettre en bouteilles."],"vn-vin-de-menthe-fraiche":["porter l’eau⟦I0⟧ à ébullition et y jeter la menthe fraîche⟦I1⟧ ; donner 5 minutes de bouillon et laisser refroidir la décoction.","Filtrer et ajouter le vin⟦I2⟧, le sucre de canne⟦I3⟧ et l’alcool⟦I4⟧.","Mettre en bouteille et consommer bien frais."],"vn-vin-de-myrtille":["Faire macérer dans une jarre les myrtilles⟦I0⟧, le vin⟦I1⟧, le miel⟦I3⟧ et l’alcool⟦I2⟧ pendant 4 semaines.","Passer la préparation au moulin manuel pour faire éclater toutes les baies.","Filtrer finement et mettre en bouteilles."],"vn-vin-aux-pruneaux":["Choisir des pruneaux⟦I0⟧ de l’année, tendres et non desséchés.","Les piquer en plusieurs endroits avec une grosse aiguille.","Les mettre dans un bocal avec le sucre⟦I3⟧, la vanille⟦I4⟧ et l’alcool⟦I2⟧.","Laisser macérer pendant 15 jours en agitant le bocal de temps en temps.","Ajouter le vin⟦I1⟧, laisser encore reposer 8 jours.","Retirer la vanille.","Presser les pruneaux dans un torchon pour en exprimer le jus.","Mélanger ce jus avec le vin, puis filtrer et mettre en bouteille."],"vn-vin-de-sauge":["Faire le sirop avec l’eau⟦I1⟧ et le sucre⟦I3⟧, puis hacher finement la sauge⟦I4⟧.","Mettre tous les composants⟦I0⟧⟦I2⟧ dans une jarre et laisser macérer 20 jours.","Filtrer finement et mettre en bouteilles.","Se bois bien frais."],"vn-vin-de-sureau":["Dissoudre le sucre⟦I3⟧ dans l’eau⟦I1⟧ et y faire éclater les baies⟦I4⟧ à petit feu.","Passer au tamis la compote obtenue.","Dans une jarre mettre tous les composants⟦I0⟧⟦I2⟧ dans une jarre et laisser macérer 10 jours.","Filtrer finement et mettre en bouteilles.","Se bois bien frais."],"vn-vin-blanc-aux-pamplemousses":["Mette le sucre⟦I1⟧ dans une casserole et verser le vin⟦I2⟧.","Faites chauffer à feu très doux, il ne faut pas que le mélange arrive à ébullition jusqu'à ce que le sucre soit complètement fondu.","Presser les 2 pamplemousses⟦I0⟧.","Laisser refroidir le vin sucré et ajouter le jus de pamplemousse."],"vn-vin-d-abricots":["Dans une grande casserole, mettre les abricots⟦I1⟧ dénoyautés, ajouter le sucre⟦I2⟧ et la cannelle⟦I3⟧ et verser dessus le vin blanc⟦I0⟧.","Poser le tout sur le feu.","Aux premiers bouillons, baisser le feu et laisser frémir 1/4 heure à 20 min.","Laisser un peu refroidir avant de couvrir pour éviter la condensation sur le couvercle.","Le vin, pour prendre toute sa saveur, doit reposer ainsi plusieurs jours.","Goûter et ajouter l'alcool de fruits⟦I4⟧.","Rajouter un petit peu de sucre si nécessaire.","Filtrer et mettre en bouteilles.","Servir très frais."],"vn-vin-d-amande-amere":["Laisser macérer 3 ou 4 semaines tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧.","Brasser et goûter régulièrement.","Rajouter du sucre si besoin.","Mettre en bouteille et consommer bien frais."],"vn-vin-d-aneth":["Broyer les graines⟦I3⟧⟦I4⟧ et le sucre⟦I2⟧ puis mélanger ces ingrédients dans le vin⟦I0⟧.","Ajouter l’alcool⟦I1⟧ et laisser mariner au moins 2 semaines.","Filtrer et mettre en bouteilles."],"vn-vin-de-brugnons":["Peler et couper en morceaux ou en tranches les brugnons⟦I0⟧.","Mettre dans une casserole les brugnons, le vin⟦I1⟧, et la vanille⟦I2⟧ fendue, les noyaux éclatés des fruits, avec l'amande.","Laisser doucement mijoter 30 minutes et écrasant les fruits.","Filtrer la préparation et laisser refroidir.","Ajouter alors l’eau de vie⟦I3⟧ et le sirop refroidi préparé avec l’eau⟦I5⟧ et le sucre⟦I4⟧.","Laisser macérer deux semaines et remuant quelques fois puis filtrer et mettre en bouteilles.","Laisser vieillir quelques mois avant consommation."],"vn-vin-de-bruyere":["Faire macérer les fleurs⟦I1⟧ dans le vin⟦I0⟧ avec les baies de genièvre⟦I2⟧ hachées.","Filtrer et sucrer⟦I3⟧ au goût, mettre en bouteilles et conserver au frais."],"vn-vin-de-camomille-au-vin-blanc":["Mettre tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧ dans un bocal.","Fermer et laisser reposer 15 jours.","Filtrer le vin et le garder dans des bouteilles couchées."],"vn-vin-de-camomille-au-vin-rouge":["Mettre tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧ dans un bocal.","Fermer et laisser reposer 15 jours.","Filtrer le vin et le garder dans des bouteilles bouchées."],"vn-vin-de-camomille-au-vin-rouge-et-aux-epices":["Prélever le zeste d'une orange⟦I6⟧ non traitée et couper-le en petites lanières.","Mettre tous les ingrédients⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I7⟧ dans un bocal, fermer hermétiquement.","Laisser macérer pendant 30 jours dans un endroit frais et sec.","Filtrer et mettre en bouteilles."],"vn-vin-de-cannelle":["Faire macérer les écorces⟦I0⟧⟦I1⟧ et le vin⟦I2⟧ pendant 1 mois.","Filtrer et remettre en bouteille."],"vn-vin-de-cartagene":["Mettre le moût⟦I0⟧ dans une Jarre et ajouter l’alcool⟦I1⟧.","Le produit doit rester au moins 3 mois dans la jarre et il faut remuer quelque fois.","A la fin de la macération bien presser, puis laisser reposer et filtrer.","En fonction du type de raisin blanc ou noir la Cartagène est plus ou moins dorée."],"vn-vin-de-cassis-1":["Ecraser les fruits⟦I0⟧, ajouter le vin rouge⟦I1⟧ et laisser macérer pendant 2 jours.","Passez ensuite le mélange au tamis.","Ajouter le sucre⟦I2⟧ et faire cuire à feu doux.","Porter à ébullition tout en remuant pendant 5 min.","Laisser refroidir la crème de cassis avant de mettre en bouteille."],"vn-vin-de-cassis-2":["Faire macérer pendant 48 heures les cassis écrasés⟦I0⟧ avec le vin⟦I1⟧, passer et égoutter.","Faire un bouillon avec un kg de sucre pour un litre de jus.","Laisser bouillir 10 minutes, puis refroidir.","Ajouter le cognac⟦I2⟧ ou l'eau de vie⟦I3⟧.","Se conserve très longtemps."],"vn-vin-de-cerises-1":["Dissoudre le sucre⟦I2⟧ dans l'eau tiède⟦I3⟧.","Mélanger tous les ingrédients et laisser macérer 1 mois, filtrer et mettre en bouteille."],"vn-vin-de-cerises-2":["Ecraser les cerises⟦I2⟧ avec leurs noyaux.","Ce sont les noyaux qui donneront le goût.","Les mettre dans une dame-jeanne à gros goulot, ou un grand bocal.","Y verser le vin⟦I1⟧, l'alcool⟦I3⟧ et rajouter le sucre⟦I4⟧.","Remuer tous les jours pendant les 15 jours de macération.","Filtrer, mettre en bouteilles et laisser un peu vieillir."],"vn-vin-de-feuilles-de-cerisier":["Cueillir les feuilles après la récolte des cerises.","Bien les laver et les essuyer.","Dans une jarre ajouter les feuilles⟦I0⟧, les vins⟦I1⟧⟦I2⟧, la cannelle écrasée⟦I5⟧, la gousse de vanille fendue⟦I6⟧, le macis⟦I7⟧ et le sucre⟦I3⟧.","Faire macérer 60 jours, puis filtrer et mettre en bouteilles.","Il est préférable de laisser vieillir quelques mois à l’ombre."],"vn-vin-de-chicoree":["Faire macérer la chicorée⟦I3⟧ dans le vin⟦I0⟧ pendant 5 jours.","Filtrer.","Faire un sirop avec l'alcool⟦I1⟧ et le sucre⟦I2⟧ et l'ajouter au vin.","Filtrer et mettre en bouteille."],"vn-vin-de-coing":["Laver puis couper les coings⟦I3⟧ en morceaux.","Tout mettre dans une jarre et laisser macérer le tout pendant 6 semaines, filtrer et mettre en bouteille."],"vn-vin-de-lectoure":["Faire macérer le zeste des oranges⟦I0⟧ dans l’alcool⟦I1⟧ pendant au moins 4 semaines dans un bocal.","Au bout de ce délai, mélanger avec le vin blanc⟦I2⟧ et le sucre⟦I3⟧ dans un grand récipient.","Remuer et laisser reposer 3 jours dans le récipient fermé.","Ensuite enlever les zestes en les pressant pour en extraire le jus, filtrer la préparation et mettre en bouteilles."],"vn-vin-d-epines":["Mélanger tous les ingrédients et laisser macérer un mois.","Puis filtrer et mettre en bouteilles."],"vn-vin-de-feuilles-de-cassis-au-vin-blanc":["Mettre tout les ingrédients dans une jarre.","Laisser macérer les feuilles⟦I2⟧ dans le vin⟦I0⟧ et l'alcool⟦I3⟧ pendant 20 jours.","Filtrer et embouteiller."],"vn-vin-de-feuilles-de-cassis-au-vin-rouge":["Laisser macérer le tout pendant 2 mois en remuant de temps en temps.","Filtrer en embouteillant."],"vn-vin-de-feuilles-de-merisier":["Laver les feuilles de merisier⟦I0⟧ et les sécher dans un torchon.","Les faire macérer avec le sucre⟦I1⟧ dans le vin⟦I2⟧ pendant 48 h.","Passé ce temps, remuer la préparation, la filtrer et y ajouter le kirsch⟦I3⟧.","Embouteiller, boucher et laisser reposer avant consommation.","Ce vin se bonifie en vieillissant."],"vn-vin-de-figues-1":["Ecraser les figues⟦I0⟧ au pilon et les mettre dans une bassine émaillée ou un pot en grès.","Verser dessus l'eau bouillante⟦I5⟧ et remuer longuement pour diluer la pâte de fruits, puis placer au chaud.","Passer Faire dissoudre les acides⟦I2⟧⟦I3⟧ et le sucre⟦I1⟧ dans un peu de jus.","Verser la dissolution dans la bonbonne avec le reste du jus, ajouter la levure⟦I4⟧ diluée dans un peu d'eau tiède.","Mélanger, laisser fermenter 6-8 jours à découvert.","Passer et filtrer le vin.","Mettre en bouteilles.","Conserver couché à la cave 1 an."],"vn-vin-de-figues-2":["Couper les figues⟦I1⟧ en 2 ou 3 morceaux.","Verser le vin⟦I0⟧ dans une casserole.","Y ajouter les figues, le sucre⟦I3⟧ et la cannelle⟦I4⟧.","Aux premiers bouillons, baisser le feu et laisser frémir ¼ heure.","Ajouter l'alcool⟦I2⟧ et laisser reposer 4 à 5 jours.","Filtrer, il se peut qu'un léger dépôt apparaisse après le filtrage.","Laisser reposer et filtrer une seconde fois.","Mettre en bouteilles.","Se sert bien frais."],"vn-vin-de-fleurs-d-acacia-robinier":["Mélanger les fleurs d'Acacia⟦I0⟧ avec le litre de vin blanc⟦I1⟧.","Rajouter le verre de calvados⟦I2⟧ et le miel d'acacia.","Laisser macérer 15 jours, puis filtrer.","Servir très frais à l'apéritif."],"vn-vin-rouge-de-framboises":["Faire macérer les fruits⟦I0⟧ écrasés dans le vin⟦I1⟧ et l'alcool⟦I3⟧ pendant 15 jours.","Retirer les fruits puis filtrer à travers une étamine dans un faitout.","Ajouter le sucre⟦I2⟧ et faire chauffer, en remuant sans faire bouillir.","Laisser refroidir, remuer et mettre en bouteilles en filtrant de nouveau."],"vn-vin-blanc-de-framboises":["Dans un pot en terre faire macérer vin⟦I1⟧ et framboises⟦I0⟧ 24 h. presser les fruits sur un tamis.","Mettre cuire le jus recueilli avec le sucre⟦I3⟧, en remuant sans arrêt.","Remplir jusqu'à ras bord des bouteilles préchauffées et les boucher tout de suite avec des capsules en caoutchouc."],"vn-vin-de-framboises-a-l-ancienne":["Faire macérer les framboises⟦I1⟧ dans le vin⟦I0⟧ en ajoutant le sucre⟦I2⟧.","Laisser reposer 15 jours en remuant souvent pour faciliter la fonte du sucre.","Filtrer soigneusement sans écraser les fruits.","Ajouter l'alcool⟦I3⟧.","Embouteiller et boucher.","Ne consommer que plusieurs mois plus tard (si possible ! !)."],"vn-vin-de-feuilles-de-framboisier":["Cueillir les feuilles⟦I2⟧ au printemps quand elles sont jeunes.","Faire macérer tous les ingrédients 15 à 20 jours en remuant de temps en temps pour faire fondre le sucre⟦I4⟧.","Retirer les feuilles, filtrer et laisser reposer.","Laisser vieillir au moins 6 mois avant de consommer.","La préparation donne un vin doux et très parfumé."],"vn-vin-rouge-de-genievre":["Ecraser les baies de genièvre⟦I0⟧ et les faire macérer dans l'eau-de-vie⟦I1⟧ pendant une semaine.","Chauffer le vin⟦I2⟧ avec le sucre⟦I3⟧ jusqu'à ébullition et l'ajouter à la macération précédente.","Mélanger Laisser reposer 15 jours puis filtrer.","Mettre en bouteilles et boucher."],"vn-vin-blanc-de-genievre":["Broyer un peu les baies⟦I0⟧ au mortier.","Verser dans un bocal.","Ajouter le vin⟦I1⟧ et le sucre⟦I2⟧.","Laisser reposer 12 jours, agiter quelques fois.","Mettre à cuire la macération le temps d'un bouillon.","Reverser dans le bocal le verre d’eau de vie⟦I3⟧.","Après 15 jours, presser sur un tamis, puis filtrer et verser dans des bouteilles."],"vn-vin-blanc-de-gentiane":["Nettoyer et brosser la racine⟦I0⟧, la découper en petits morceaux.","Mettre à macérer la gentiane dans l'eau de vie⟦I2⟧ pendant 10 jours.","Ajouter le sucre⟦I3⟧ dans le vin blanc⟦I1⟧ et bien faire dissoudre.","Après 10 jours, filtrer, mettre en bouteilles, bien."],"vn-vin-rouge-de-gentiane":["Nettoyer, laver et brosser la racine⟦I0⟧, la découper en morceaux.","La faire infuser dans un bocal avec le vin⟦I1⟧ pendant 10 jours.","Passé ce temps, filtrer.","Faire bouillir l'eau⟦I2⟧ et le sucre⟦I3⟧.","Retirer du feu au premier bouillon et ajouter le sirop refroidi au vin.","Mettre en bouteilles et fermer.","Laisser reposer quelques jours avant de déguster."],"vn-vin-de-gingembre":["Casser en tout petits morceaux le gingembre⟦I2⟧, y ajouter les clous de girofle⟦I3⟧.","Faire macérer dans le vin⟦I0⟧ et l'alcool⟦I1⟧ pendant deux semaines puis faire dissoudre le sucre⟦I4⟧.","Filtrer, mettre en bouteilles et laisser vieillir."],"vn-vin-de-guignolet":["Faire cuire les cerises⟦I0⟧ avec le sucre⟦I1⟧ pendant 30 minutes.","Prélever le jus, mettre 1/2 litre d'eau de vie⟦I3⟧ pour 1/2 litre de jus de cerises.","Ajouter la vanille⟦I4⟧ et laisser macérer 15 jours.","Filtrer et ajouter 2 litres de vin rouge⟦I2⟧."],"vn-vin-de-kiwis":["Peler et couper en morceaux ou en tranches les kiwis⟦I0⟧.","Préparer le sirop avec le sucre⟦I4⟧ et l’eau⟦I5⟧ puis laisser refroidir.","Mette dans une jarre les fruits, l’alcool⟦I3⟧, le sirop et le zeste de l’orange⟦I2⟧.","Fermer et laisser macérer 1 mois à l’ombre.","Passer et filtre la préparation, mettre en bouteilles et laisser gentiment vieillir 3 ou 4 mois avant de consommer."],"vn-vin-de-litchis":["Peler les litchis⟦I0⟧ et ôter les noyaux, mettre les fruits dans une jarre avec la vanille⟦I2⟧ fendue, le vin⟦I1⟧, le sirop⟦I4⟧, le rhum⟦I3⟧.","Fermer et laisser macérer 30 jours à l’ombre, en remuant régulièrement.","Passer et filtrer la préparation, mettre en bouteilles et laisser reposer 2 mois avant consommation."],"vn-vin-de-mai":["Mettre à macérer les fleurs⟦I1⟧ dans un litre de vin blanc⟦I0⟧ bouillant.","Dissoudre le sucre⟦I2⟧ et laisser refroidir le mélange.","Ajouter l'alcool⟦I3⟧.","Passer finement et mettre en bouteilles, ne pas consommer avant un mois.","Le vin de mai devient légèrement pétillant.","Il est à boire comme apéritif."],"vn-vin-blanc-de-mirabelle":["Ouvrir les fruits⟦I2⟧ et casser une poignée de noyaux.","Mélanger tous les ingrédients puis laisser macérer 4 semaines dans une jarre.","Filtrer et mettre en bouteilles.","Il s'améliore énormément en vieillissant."],"vn-vin-de-noyer":["Laisser macérer les feuilles⟦I1⟧ et le vin⟦I0⟧ pendant 10 jours, Dissoudre le sucre⟦I3⟧ dans le mélange puis ajouter l’eau de vie⟦I2⟧.","Laisser reposer 10 jours de plus, puis filtrer et mettre en bouteilles."],"vn-vin-de-noix-aux-epices":["Cueillez les noix vertes juste formées à l'intérieur.","Coupez-les avec leur brou en deux ou quatre morceaux.","Mettez-les⟦I0⟧ dans un grand bocal avec le vin, la vanille, la cannelle, le macis et l'eau-de-vie.","Bouchez le bocal et laissez macérer pendant 3 mois, en remuant de temps en temps le mélange.","Une fois cette période écoulée, filtrez, ajoutez le sucre et laissez-le fondre pendant quelques heures.","Mettez en bouteilles et bouchez.","Cette eau de noix s'améliore en vieillissant."],"vn-vin-de-noix-aux-clous-de-girofle":["Coupez les noix en plusieurs morceaux selon leur grosseur.","Les mettre⟦I0⟧ dans un grand bocal.","Ajoutez les clous de girofle⟦I1⟧ broyés, puis versez l'eau-de vie⟦I3⟧.","Les noix doivent baigner complètement.","Fermez le bocal, le placer dans un endroit tempéré, laissez macérer 2 mois.","Lorsque l'eau de vie a pris une teinte brun foncé, presque noire, ajoutez le vin rouge⟦I2⟧ dans le bocal, puis le sucre⟦I4⟧.","Rebouchez et laissez macérer encore une semaine.","Filtrez alors le contenu du bocal.","Mettez le vin de noix en bouteilles et bouchez-les soigneusement.","Entreposez-les dans un endroit frais, si possible dans l'obscurité.","Patientez 2 mois avant de consommer."],"vn-vin-de-peches":["Dans un récipient, mettre tous les ingrédients, fermer avec un film plastique ou un couvercle hermétique, laisser macérer.","Après deux semaines de macération, filtrer et mettre en bouteille.","Cette recette donne un rosé apéritif très finement parfumé, c'est un délice servi bien frais."],"vn-vin-de-pissenlits":["Verser l'eau bouillante⟦I0⟧ sur les fleurs⟦I1⟧ et laisser infuser 24 heures, ajouter le sucre⟦I2⟧, les raisins⟦I3⟧ et les fruits⟦I4⟧ coupés en morceaux, les clous de girofle⟦I5⟧.","Remuer le tout, tous les jours pendant 3 semaines.","Filtrer et mettre dans des bouteilles bouchées avec du coton.","Au bout de 40 jours, filtrer à nouveau.","Mettre en bouteilles bouchées Sans alcool."],"vn-vin-de-pousses-d-epine":["Préparez la recette du vin Pousse d'épine directement en bonbonne.","Mélanger tous les ingrédients et laisser macérer pendant 4 semaines en remuant régulièrement.","Filtrer et mettre en bouteilles.","Se déguste très frais."],"vn-vin-de-prunelles":["Mélanger tous ces ingrédients après avoir écrasé un peu les prunelles⟦I0⟧.","Laisser vieillir le mélange au minimum 6 mois dans un tonnelet ou dans une grande bouteille en plastique d'eau minérale (de 5 litres).Prendre soin de laisser le bouchon entrouvert pour laisser les gaz de fermentation s'échapper.","Filtrer à l'issue des 6 mois.","Ce vin rosé légèrement pétillant devient encore meilleur si on a la patience d'attendre quelques mois voir si la bouteille es bien bouchée 1 à 2 ans."],"vn-vin-de-prele":["Hacher les feuilles de prêle⟦I0⟧⟦I1⟧, puis faire macérer 3 semaines dans de l’eau de vie⟦I2⟧.","Dissoudre le miel⟦I3⟧ dans le vin⟦I4⟧, tout mélanger et laisser 15 jours de plus.","Passer la préparation et mettre au repos dans une jarre quelques semaines.","Filtrer et mettre en bouteilles.","La plante a des propriétés reminéralisantes et diurétiques qui aident à soulager les articulations."],"vn-vin-de-roses":["Oter les pétales et les passer brièvement sous l’eau, il est nécessaire d’avoir des roses non traitées.","Couper la partie blanche des pétales et les mettre sur une surface plane pendant 1 semaine pour les faire sécher.","Mettre les pétales⟦I1⟧ dans un bocal, ajouter le vin⟦I0⟧ et le sucre⟦I2⟧.","Bien boucher et laisser au soleil 20 jours.","Filtrer et mettre en bouteille, laisser reposer 2 semaines avant de consommer bien frais."],"vn-vin-de-trouspinette":["Laisser macérer tous les ingrédients pendants 6 semaines puis filtrer et mettre en bouteilles.","Laisser vieillir quelques mois avant de consommer bien frais."],"vn-vin-d-eucalyptus":["Faire macérer les feuilles⟦I1⟧ et le sucre⟦I2⟧ dans le vin rouge⟦I0⟧ pendant 20 jours.","Filtrer et mettre en bouteille, se boit bien frais."],"vn-vin-d-hysope":["Ciseler finement toutes les feuilles⟦I0⟧⟦I1⟧⟦I2⟧⟦I3⟧, concasser le genièvre⟦I4⟧ et tout plonger dans l’alcool⟦I5⟧ pendant 8 semaines.","Filtrer alors le mélange et l’ajouter au vin⟦I6⟧ dans lequel on aura fait dilluer le sucre⟦I7⟧.","Laisser décanter une semaine, filtrer de nouveau et mettre en bouteilles."],"vn-vin-rouge-d-orange":["Faire macérer les peaux d'orange⟦I1⟧ dans le vin⟦I0⟧ pendant 20 jours.","Puis retirer un peu de ce liquide pour y faire fondre le sucre⟦I3⟧.","Mélanger le tout avec le verre d'alcool⟦I2⟧.","Ajouter la cannelle⟦I4⟧.","Filtrer et mettre en bouteille.","S'améliore beaucoup avec un temps de repos.","On peut, avec cette même recette, remplacer les oranges par des pamplemousses, des clémentines ou des mandarines en adaptant le nombre de peaux."],"vn-vin-blanc-d-orange":["Faire macérer 30 jours tous les ingrédients dans un bocal fermé.","Oter les zestes et la cannelle et remettre en bouteilles."],"vn-vin-rouge-epice-chaud-glogi-finlande":["Verser le vin rouge⟦I0⟧ dans une casserole.","Ajouter cannelle⟦I4⟧, clous de girofle⟦I3⟧ et sucre⟦I5⟧.","Chauffer le mélange et laisser sur le feu pendant 10 minutes sans faire bouillir.","Verser la vodka⟦I6⟧, filtrer et servir chaud avec quelques amandes⟦I1⟧ et raisins⟦I2⟧ au fond du verre."],"vn-vin-fortifiant-au-persil":["Cuire à petits bouillon le persil⟦I3⟧ dans le vin⟦I0⟧ et le vinaigre⟦I1⟧, Passer le mélange et laisser refroidir un peu.","Dissoudre le miel⟦I2⟧ et ajouter l’alcool⟦I4⟧.","Laisser reposer et mettre en bouteilles.","Se prend en cure d’une semaine à raison d’un petit verre avant chaque repas.","C’est un fortifiant cardiaque."],"vn-vin-tonique-du-pape":["Broyer au pilon les épices⟦I2⟧⟦I3⟧⟦I4⟧⟦I5⟧⟦I6⟧⟦I7⟧ et tout mélanger dans l’alcool⟦I1⟧.","Laisser macérer 6 semaines.","Dissoudre le miel⟦I8⟧ dans le vin⟦I0⟧ et ajouter la macération filtrée.","Verser le tout dans une jarre en verre et exposer 1 mois au soleil.","Filtrer et mettre en bouteilles.","Laisser reposer quelques semaines avant de consommer.","Cette préparation est un fortifiant à prendre en début d’hiver, faire un cure de quelques jours, prendre un petit verre le matin."]};
